comms.text:
@1 וּשְׁמַע יִתְרוֹ רַבָּא דְמִדְיָן חֲמוּהִי דְמשֶׁה יַת כָּל דִי עֲבַד יְיָ לְמשֶׁה וּלְיִשְׂרָאֵל עַמֵהּ אֲרֵי אַפִּיק יְיָ יָת יִשְׂרָאֵל מִמִצְרָיִם:
@2 וּדְבַר יִתְרוֹ חֲמוּהִי דְמשֶׁה יָת צִפֹּרָה אִתַּת משֶׁה בָּתַר דְפַטְרַהּ:
@3 וְיָת תְּרֵין בְּנָהָא דִי שׁוּם חַד גֵרְשֹׁם אֲרֵי אֲמַר דַיָר הֲוֵיתִי בְּאַרְעָא נוּכְרָאָה:
@4 וְשׁוּם חַד אֱלִיעֶזֶר אֲרֵי אֱלָהָא דְאַבָּא הֲוָה בְסַעְדִי וְשֵׁזְבַנִי מֵחַרְבָּא דְפַרְעֹה:
@5 וַאֲתָא יִתְרוֹ חֲמוּהִי דְמשֶׁה וּבְנוֹהִי וְאִתְּתֵהּ לְוָת משֶׁה לְמַדְבְּרָא דִי הוּא שָׁרֵי תַמָן לְטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ:
@6 וַאֲמַר לְמשֶׁה אֲנָא חֲמוּךְ יִתְרוֹ אָתֵי לְוָתָךְ וְאִתְּתָךְ וּתְרֵין בְּנָהָא עִמַהּ:
@7 וּנְפַק משֶׁה לְקַדָמוּת חֲמוּהִי וּסְגִיד וּנְשִׁיק לֵהּ וּשְׁאִילוּ גְבַר לְחַבְרֵהּ לִשְׁלָם וְעַלוּ לְמַשְׁכְּנָא:
@8 וְאִשְׁתָּעִי משֶׁה לַחֲמוּהִי יָת כָּל דִי עֲבַד יְיָ לְפַרְעֹה וּלְמִצְרָאֵי עַל עֵסַק יִשְׂרָאֵל יָת כָּל עַקְתָא דִי אַשְׁכַּחְתִּנוּן בְּאָרְחָא וְשֵׁזְבָנוּן יְיָ:
@9 וַחֲדִי יִתְרוֹ עַל כָּל טַבְתָא דִי עֲבַד יְיָ לְיִשְׂרָאֵל דִי שֵׁזְבָנוּן מִידָא דְמִצְרָאֵי:
@10 וַאֲמַר יִתְרוֹ בְּרִיךְ יְיָ דִי שֵׁזִיב יָתְכוֹן מִידָא דְמִצְרָאֵי וּמִידָא דְפַרְעֹה דִי שֵׁזִיב יָת עַמָא מִתְּחוֹת מַרְוַת מִצְרָאֵי:
@11 כְּעַן יְדַעְנָא אֲרֵי רַב יְיָ וְלֵית אֱלָּהּ בַּר מִנֵהּ אֲרֵי בְּפִתְגָמָא דִי חַשִׁיבוּ מִצְרָאֵי לְמִדַן יָת יִשְׂרָאֵל בֵּהּ דָנִנוּן:
@12 וְקָרִיב יִתְרוֹ חֲמוּהִי דְמשֶׁה עֲלָוָן וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ וַאֲתָא אַהֲרֹן וְכֹל סָבֵי יִשְׂרָאֵל לְמֵיכַל לַחְמָא עִם חֲמוּהִי דְמשֶׁה קֳדָם יְיָ:
@13 וַהֲוָה מִיוֹמָא דְבַתְרוֹהִי וִיתֵיב משֶׁה לְמִדַן יָת עַמָא וְקָם עַמָא עִלָוֹהִי דְמשֶׁה מִן צַפְרָא עַד רַמְשָׁא:
@14 וַחֲזָא חֲמוּהִי דְמשֶׁה יָת כָּל דִי הוּא עָבֵד לְעַמָא וַאֲמַר מָא פִתְגָמָא הָדֵין דִי אַתְּ עָבֵד לְּעַמָא מָה דֵין אַתְּ יָתֵב בִּלְחוֹדָךְ וְכָל עַמָא קָיְמִין עִלָוָךְ מִן צַפְרָא עַד רַמְשָׁא:
@15 וַאֲמַר משֶׁה לַחֲמוּהִי אֲרֵי אָתָן לְוָתִי עַמָא לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@16 כַּד הֲוֵי לְהוֹן דִינָא אָתָן לְוָתִי וְדָאִינְנָא בֵּין גַבְרָא וּבֵין חַבְרֵהּ וּמְהוֹדַעְנָא לְהוֹן יָת קְיָמַיָא דַיְיָ וְיָת אוֹרָיָתֵהּ:
@17 וַאֲמַר חֲמוּהִי דְמשֶׁה לֵהּ לָא תַקִין פִּתְגָמָא דְאַתְּ עָבֵד:
@18 מִלְאָה תִלְאֶה אַף אַתְּ אַף עַמָא הָדֵין דִעִמָךְ אֲרֵי יַקִיר מִנָךְ פִּתְגָמָא לָא תִכּוֹל לְמֶעְבְּדֵהּ בִּלְחוֹדָךְ:
@19 כְּעַן קַבֵּל מִנִי אֲמַלְכִנָךְ וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדָךְ הֱוֵי אַתְּ לְעַמָא (תְּבַע) אוּלְפַן מִן קֳדָם יְיָ וּתְהֵי מַיְתִי אַתְּ יָת פִּתְגָמַיָא לִקֳדָם יְיָ:
@20 וְתַזְהַר יָתְהוֹן יָת קְיָמַיָא וְיָת אוֹרַיְתָא וּתְהוֹדַע לְהוֹן יָת אוֹרְחָא דִיְהָכוּן בַּהּ וְיָת עוֹבָדָא דִיַעְבְּדוּן:
@21 וְאַתְּ תֶּחֶזֵי מִכָּל עַמָא גֻבְרִין דְחֵילָא דַחֲלַיָא דַיְיָ גֻבְרִין דִקְשׁוֹט דְסָנָן לְקַבָּלָא מָמוֹן וּתְמַנֵי עֲלֵיהוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@22 וִידוּנוּן יָת עַמָא בְּכָל עִדַן וִיהֵי כָּל פִּתְגַם רַב יַיְתוּן לְוָתָךְ וְכָל פִּתְגַם זְעֵיר יְדוּנוּן אִנוּן וְיִקְלוּן מִנָךְ וִיסוֹבְרוּן עִמָךְ:
@23 אִם יָת פִּתְגָמָא הָדֵין תַּעְבֵּד וִיפַקְדִנָךְ יְיָ וְתִכּוֹל לְמֵיקָם וְאַף כָּל עַמָא הָדֵין עַל אַתְרֵהּ יְהַךְ בִּשְׁלָם:
@24 וְקַבִּיל משֶׁה לְמֵימְרָא דַחֲמוּהִי וַעֲבַד כֹּל דִי אֲמָר:
@25 וּבְחַר משֶׁה גֻבְרִין דְחֵילָא מִכָּל יִשְׂרָאֵל וּמַנִי יָתְהוֹן רֵישִׁין עַל עַמָא רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@26 וְדַיְנִין יָת עַמָא בְּכָל עִדָן יָת פִתְגַם קָשֵׁי מַיְתִין לְוָת משֶׁה וְכָל פִּתְגַם זְעֵיר דָיְנִין אִנוּן:
@27 וְשַׁלַח משֶׁה יָת חֲמוּהִי וַאֲזַל לֵהּ לְאַרְעֵהּ:
@28 בְּיַרְחָא תְּלִיתָאָה לְמִפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם בְּיוֹמָא הָדֵין אֲתוֹ לְמַדְבְּרָא דְסִינָי:
@29 וּנְטָלוּ מֵרְפִידִים וַאֲתוֹ לְמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּמַדְבְּרָא וּשְׁרָא תַמָן יִשְׂרָאֵל לָקֳבֵל טוּרָא:
@30 וּמשֶׁה סְלֵק לִקֳדָם יְיָ וּקְרָא לֵהּ יְיָ מִן טוּרָא לְמֵימַר כִּדְנַן תֵּימַר לְבֵית יַעֲקֹב וּתְחַוִי לִבְנֵי יִשְׂרָאֵל:
@31 אַתּוּן חֲזִתּוּן דִי עֲבָדִית לְמִצְרָיִם וּנְטָלִית (נ''א וְאַטְּלִית) יָתְכוֹן כִּדְעַל גַדְפֵי נִשְׁרִין וְקָרֵבִית יָתְכוֹן לְפָלְחָנִי:
@32 וּכְעַן אִם קַבָּלָא תְקַבְּלוּן לְמֵימְרִי וְתִטְרוּן יָת קְיָמִי וּתְהוֹן קֳדָמַי חַבִּיבִין מִכָּל עַמְמַיָא אֲרֵי דִי לִי כָּל אַרְעָא:
@33 וְאַתּוּן תְּהוֹן קֳדָמַי מַלְכִין כָּהֲנִין וְעַם קַדִישׁ אִלֵין פִּתְגָמַיָא דִי תְמַלֵל עִם בְּנֵי יִשְׂרָאֵל:
@34 וַאֲתָא משֶׁה וּקְרָא לְסָבֵי עַמָא וְסַדַר קֳדָמֵיהוֹן יָת כָּל פִּתְגָמַיָא הָאִלֵין דִפַקְדֵיהּ יְיָ:
@35 וַאֲתִיבוּ כָל עַמָא כַּחֲדָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וַאֲתֵיב משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@36 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מִתְגְלִי לָךְ בְּעֵיבָא דַעֲנָנָא בְּדִיל דְיִשְׁמַע עַמָא בְּמַלָלוּתִי עִמָךְ וְאַף בָּךְ יְהֵימְנוּן לְעָלָם וְחַוִי משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@37 וַאֲמַר יְיָ לְמשֶׁה אִזֵיל לְוָת עַמָא וּתְזַמִנוּן יוֹמָא דֵין וּמְחָר וִיחַוְרוּן לְבוּשֵׁיהוֹן:
@38 וִיהוֹן זְמִינִין לְיוֹמָא תְלִיתָאָה אֲרֵי בְּיוֹמָא תְלִיתָאָה יִתְגְלִי יְיָ לְעֵינֵי כָל עַמָא עַל טוּרָא דְסִינָי:
@39 וּתְתַחֵם יָת עַמָא סְחוֹר סְחוֹר לְמֵימַר אִסְתַּמָרוּ לְכוֹן מִלְמִסַק בְּטוּרָא וּלְמִקְרַב בְּסוֹפֵהּ כָּל דְיִקְרַב בְּטוּרָא אִתְקְטָלָא יִתְקְטֵל:
@40 לָא תִקְרַב בֵּהּ יְדָא אֲרֵי אִתְרְגָמָא יִתְרְגֵם אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי אִם בְּעִירָא אִם אֱנָשָׁא לָא יִתְקַיָם בְּמֵיגַד שׁוֹפָרָא אִנוּן מְרָשָׁן לְמִסַק בְּטוּרָא:
@41 וּנְחַת משֶׁה מִן טוּרָא לְוָת עַמָא וְזַמִין יָת עַמָא וְחַוָרוּ לְבוּשֵׁיהוֹן:
@42 וַאֲמַר לְעַמָא הֱווֹ זְמִינִין לִתְלָתָא יוֹמִין לָא תִקְרְבוּן לְצַד אִתְּתָא:
@43 וַהֲוָה בְיוֹמָא תְלִיתָאָה בְּמֶהֱוֵי צַפְרָא וַהֲוָה קָלִין וּבַרְקִין וַעֲנָנָא תַקִיף עַל טוּרָא וְקַל שׁוֹפָרָא תַּקִיף לַחֲדָא וְזָע כָּל עַמָא דִי בְמַשְׁרִיתָא:
@44 וְאַפֵיק משֶׁה יָת עַמָא לְקַדָמוּת מֵימְרָא דַיְיָ מִן מַשְׁרִיתָא וְאִתְעַתָּדוּ בְּשִׁפּוֹלֵי טוּרָא:
@45 וְטוּרָא דְסִינַי תָּנַן כֻּלֵהּ מִן קֳדָם דְאִתְגְלִי עֲלוֹהִי יְיָ בְּאֶשָׁתָא וּסְלִיק תְּנָנֵהּ כִּתְנָנָא דְאַתּוּנָא וְזָע כָּל טוּרָא לַחֲדָא:
@46 וַהֲוָה קַל שׁוֹפָרָא אָזֵל וְתָקֵף לַחֲדָא משֶׁה מְמַלֵל וּמִן קֳדָם יְיָ מִתְעֲנֵי לֵהּ בְקָל:
@47 וְאִתְגְלִי יְיָ עַל טוּרָא דְסִינַי לְרֵישׁ טוּרָא וּקְרָא יְיָ לְמשֶׁה לְרֵישׁ טוּרָא וּסְלִיק משֶׁה:
@48 וַאֲמַר יְיָ לְמשֶׁה חוּת אַסְהֵיד בְּעַמָא דִילְמָא יְפַגְרוּן קֳדָם יְיָ לְמֶחֱזֵי וְיִפֵּל מִנְהוֹן סַגִי:
@49 וְאַף כָּהֲנַיָא דִקְרִיבִין לְשַׁמָשָׁא קֳדָם יְיָ יִתְקַדְשׁוּן דִילְמָא יִקְטוֹל בְּהוֹן יְיָ:
@50 וַאֲמַר משֶׁה קֳדָם יְיָ לָא יִכּוֹל עַמָא לְמִסַק לְטוּרָא דְסִינַי אֲרֵי אַתְּ אַסְהֵדְתָּ בָּנָא לְמֵימַר תַּחִים יָת טוּרָא וְקַדְשֵׁהּ:
@51 וַאֲמַר לֵהּ יְיָ אִזֵיל חוּת וְתִסַק אַתְּ וְאַהֲרֹן עִמָךְ וְכָהֲנַיָא וְעַמָא לָא יְפַגְרוּן לְמִסַק לִקֳדָם יְיָ דִילְמָא יִקְטוֹל בְּהוֹן:
@52 וּנְחַת משֶׁה לְעַמָא וַאֲמַר לְהוֹן:
@53 וּמַלִיל יְיָ יָת כָּל פִּתְגָמַיָא הָאִלֵין לְמֵימָר:
@54 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּיקְתָּךְ מֵאַרְעָא דְמִ צְרַיִם מִבֵּית עַבְדוּתָא:
@55 לָא יְהֵי לָךְ אֱלָהּ אָחֳרָן בַּר מִנִי:
@56 לָא תַעְבֵּד לָךְ צֶלֶם וְכָל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@57 לָא תִסְגֻד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מָרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשָׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵי בָּתַר אֲבָהָתְהוֹן:
@58 וְעָבֵד טִּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְרֵי פִקוֹדָי:
@59 לָא תֵימֵי יָת שְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יִזַכֵּי יְיָ יָת דִיֵימֵי בִשְׁמֵהּ לְשִׁקְרָא:
@60 הֲוֵי דְכִיר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ:
@61 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@62 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עִבִדְתָּא אַתְּ וּבְרָךְ וּבְרַתָּךְ עַבְדָךְ וְאַמְתָךְ וּבְעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ:
@63 אֲרֵי שִׁתָּא יוֹמִין עֲבַד יְיָ יָת שְׁמַיָא וְיָת אַרְעָא יָת יַמָא וְיָת כָּל דִי בְהוֹן וְנָח בְּיוֹמָא שְׁבִיעָאָה עַל כֵּן בָּרִיךְ יְיָ יָת יוֹמָא דְשַׁבְּתָא וְקַדְשֵׁהּ:
@64 יַקַר יָת אָבוּךְ וְיָת אִמָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@65 לָא תִקְטוֹל נְפָשׁ לָא תְגוּף לָא תִגְנוּב לָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@66 לָא תַחְמֵד בֵּית חַבְרָךְ לָא תַחְמֵד אִתַּת חַבְרָךְ וְעַבְדֵהּ וְאַמְתֵהּ וְתוֹרֵהּ וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@67 וְכָל עַמָא חָזָן יָת קָלַיָא וְיָת בָּעוֹרַיָא וְיָת קַל שׁוֹפָרָא וְיָת טוּרָא תָּנֵן וַחֲזָא עַמָא וְזָעוּ וְקָמוּ מֵרָחִיק:
@68 וַאֲמָרוּ לְמשֶׁה מַלֵל אַתְּ עִמָנָא וּנְקַבֵּל וְלָא יִתְמַלֵל עִמָנָא מִן קֳדָם יְיָ דִילְּמָא נְמוּת:
@69 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אֲרֵי בְּדִיל לְנַסָאָה יָתְכוֹן אִתְגְלִי לְכוֹן יְקָרָא דַיְיָ וּבְדִיל דִתְהֵי דַחַלְתֵּהּ עַל אַפֵּיכוֹן בְּדִיל דְלָא תְחוּבוּן:
@70 וְקָם עַמָא מֵרָחִיק וּמשֶׁה קָרֵב לְצַד אַמִיטְּתָא דִתַמָן יְקָרָא דַיְיָ:
@71 וַאֲמַר יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל אַתּוּן חֲזִיתּוּן אֲרֵי מִן שְׁמַיָא מַלֵילִית עִמְכוֹן:
@72 לָא תַעְבְּדוּן קֳדָמָי דַחֲלָן דִכְסַף וְדַחֲלָן דִדְהַב לָא תַעְבְּדוּן לְכוֹן:
@73 מַדְבַּח אַדְמְתָא תַּעְבֵּד קֳדָמַי וּתְהֵי דַבָּח עֲלוֹהִי יָת עֲלָוָתָךְ וְיָת נְכַס קוּדְשָׁךְ מִן עָנָךְ וּמִן תּוֹרָךְ בְּכָל אַתְרָא דִי אַשְׁרֵי יָת שְׁכִנְתִּי לְתַמָן אֶשְׁלַח בִּרְכְּתִי לָךְ וֶאֱבָרֵכִנָךְ:
@74 וְאִם מַדְבַּח אַבְנִין תַּעְבֵּד קֳדָמַי לָא תִבְנֵי יָתְהוֹן פְּסִילָן לָא תְרִים חַרְבָּךְ עֲלַהּ וּתְחַלְלִנַהּ:
@75 וְלָא תִסַק בְּדַרְגִין עַל מַדְבְּחִי דְלָא תִתְגְלֵי עֶרְיְתָךְ עֲלוֹהִי: פפפ:

@1 **וישמע יתרו.** מה שמועה שמע ובא, קריעת ים סוף ומלחמת עמלק: **יתרו.** שבע שמות נקראו לו רעואל, יתר, יתרו, חובב, חבר, קני, פוטיאל. יתר, על שם שיתר פרשה אחת בתורה (להלן פסוק כא) ואתה תחזה. יתרו לכשנתגיר וקים המצות הוסיפו לו אות אחת על שמו. חובב שחבב את התורה. וחובב הוא יתרו, שנאמר (שופטים ד יא) מבני חובב חותן משה. ויש אומרים רעואל אביו של יתרו היה, ומה הוא אומר (שמות ב יח) ותבאנה אל רעואל אביהן, שהתינוקות קורין לאבי אביהן אבא. בספרי: **חתן משה.** כאן היה יתרו מתכבד במשה, אני חותן המלך ולשעבר היה משה תולה הגדלה בחמיו, שנאמר (שמות ד יח) וישב אל יתר חותנו: **למשה ולישראל.** שקול משה כנגד כל ישראל: **את כל אשר עשה.** להם בירידת המן ובבאר ובעמלק: **כי הוציא ה'** וגו' **.** זו גדולה על כלם:
@2 **אחר שלוחיה.** כשאמר לו הקדוש ברוך הוא במדין (שמות ד יט) לך שוב מצרים, (שם כ) ויקח משה את אשתו ואת בניו גו' ויצא אהרן לקראתו, (שם כז) ויפגשהו בהר האלהים. אמר לו מי הם הללו. אמר לו זו היא אשתי שנשאתי במדין ואלו בני. אמר לו והיכן אתה מוליכן. אמר לו למצרים. אמר לו על הראשונים אנו מצטערים ואתה בא להוסיף עליהם. אמר לה לכי אל בית אביך, נטלה שני בניה והלכה לה:
@4 **ויצלני מחרב פרעה.** כשגלו דתן ואבירם על דבר המצרי ובקש להרג את משה, נעשה צוארו כעמוד של שיש:
@5 **אל המדבר.** אף אנו יודעין שבמדבר היו, אלא בשבחו של יתרו דבר הכתוב, שהיה יושב בכבודו של עולם ונדבו לבו לצאת אל המדבר, מקום תהו, לשמוע דברי תורה:
@6 **ויאמר אל משה.** על ידי שליח: **אני חתנך יתרו** וגו' **.** אם אין אתה יוצא בגיני צא בגין אשתך, ואם אין אתה יוצא בגין אשתך צא בגין שני בניה:
@7 **ויצא משה.** כבוד גדול נתכבד יתרו באותה שעה, כיון שיצא משה יצא אהרן נדב ואביהוא, ומי הוא שראה את אלו יוצאין ולא יצא: **וישתחו וישק לו.** איני יודע מי השתחוה למי, כשהוא אומר איש לרעהו, מי הקרוי איש, זה משה, שנאמר (במדבר יב ג) והאיש משה:
@8 **ויספר משה לחתנו.** למשוך את לבו לקרבו לתורה: **את כל התלאה.** שעל הים ושל עמלק: **התלאה.** למ''ד אל''ף מן היסוד של התבה והתי''ו הוא תקון ויסוד הנופל ממנו לפרקים, וכן תרומה, תנופה, תקומה, תנואה:
@9 **ויחד יתרו.** וישמח יתרו, זהו פשוטו ומדרשו נעשה בשרו חדודין חדודין, מצר על אבוד מצרים, הינו דאמרי אינשי גיורא עד עשרה דרי לא תבזי ארמאה באפיה: **על כל הטובה.** טובת המן והבאר והתורה. ועל כלן אשר הצילו מיד מצרים, עד עכשיו לא היה עבד יכול לברוח ממצרים, שהיתה הארץ מסגרת, ואלו יצאו ששים רבוא:
@10 **אשר הציל אתכם מיד מצרים.** אמה קשה: **ומיד פרעה.** מלך קשה: **מתחת יד מצרים.** כתרגומו לשון רדוי ומרות היד שהיו מכבידים עליהם, היא העבודה:
@11 **עתה ידעתי.** מכירו הייתי לשעבר ועכשיו ביותר: **מכל האלהים.** מלמד שהיה מכיר בכל עבודה זרה שבעולם שלא הניח עבודה זרה שלא עבדה: **כי בדבר אשר זדו עליהם.** כתרגומו במים דמו לאבדם והם נאבדו במים: **אשר זדו.** אשר הרשיעו. ורבותינו דרשוהו לשון (בראשית כה כט) ויזד יעקב נזיד, בקדרה אשר בשלו בה, נתבשלו:
@12 **עלה.** כמשמעה שהיא עולה כליל: **וזבחים.** שלמים: **ויבא אהרן** וגו' **.** ומשה היכן הלך, והלא הוא שיצא לקראתו וגרם לו את כל הכבוד, אלא שהיה עומד ומשמש לפניהם: **לפני האלהים.** מכאן שהנהנה מסעודה שתלמידי חכמים מסבין בה כאלו נהנה מזיו השכינה:
@13 **ויהי ממחרת.** מוצאי יום הכפורים היה, כך שנינו בספרי, ומהו ממחרת, למחרת רדתו מן ההר. ועל כרחך אי אפשר לומר אלא ממחרת יום הכפורים, שהרי קודם מתן תורה אי אפשר לומר (פסוק טז) והודעתי את חקי וגו' , ומשנתנה תורה עד יום הכפורים לא ישב משה לשפוט את העם, שהרי בשבעה עשר בתמוז ירד ושבר את הלוחות, ולמחר עלה בהשכמה ושהה שמונים יום וירד ביום הכפורים. ואין פרשה זו כתובה כסדר, שלא נאמר ויהי ממחרת עד שנה שניה, אף לדברי האומר יתרו קדם מתן תורה בא, שלוחו אל ארצו לא היה אלא עד שנה שניה, שהרי נאמר כאן (פסוק כז) וישלח משה את חתנו ומצינו במסע הדגלים שאמר לו משה (במדבר י כט) נוסעים אנחנו אל המקום וגו' , (שם לא) אל נא תעזוב אותנו, ואם זו קדם מתן תורה, מששלחו והלך היכן מצינו שחזר ואם תאמר שם לא נאמר יתרו אלא חובב, ובנו של יתרו היה, הוא חובב הוא יתרו, שהרי כתיב (שופטים ד יא) מבני חובב חותן משה: **וישב משה** וגו' **ויעמד העם.** יושב כמלך וכלן עומדים, והקשה הדבר ליתרו שהיה מזלזל בכבודן של ישראל והוכיחו על כך, שנאמר (פסוק יד) מדוע אתה יושב לבדך וכלם נצבים: **מן הבקר עד הערב.** אפשר לומר כן, אלא כל דין שדן דין אמת לאמתו אפלו שעה אחת, מעלה עליו הכתוב כאלו עוסק בתורה כל היום, וכאלו נעשה שותף להקדוש ברוך הוא במעשה בראשית, שנאמר בו (בראשית א ה) ויהי ערב ויהי בקר יום אחד:
@15 **כי יבא.** כמו כי בא, לשון הוה: **לדרש אלהים.** כתרגומו למתבע אלפן, לשאול תלמוד מפי הגבורה:
@16 **כי יהיה להם דבר בא.** מי שיהיה לו דבר בא אלי:
@17 **ויאמר חתן משה.** דרך כבוד קוראו הכתוב חותנו של מלך:
@18 **נבל תבל.** כתרגומו. ולשונו לשון כמישה פליישטרי''ר בלעז . כמו (ירמיה ח יג) והעלה נבל, (ישעיה לד ד) כנבול עלה מגפן וגו' , שהוא כמוש על ידי חמה ועל ידי קרח, וכחו תש ונלאה: **גם אתה.** לרבות אהרן וחור ושבעים זקנים: **כי כבד ממך.** כבדו רב יותר מכחך:
@19 **איעצך ויהי אלהים עמך.** בעצה, אמר לו צא המלך בגבורה: **היה אתה לעם מול האלהים.** שליח ומליץ בינותם למקום, ושואל משפטים מאתו: **את הדברים.** דברי ריבותם:
@21 **ואתה תחזה.** ברוח הקדש שעליך: **אנשי חיל.** עשירים, שאין צריכין להחניף ולהכיר פנים: **אנשי אמת.** אלו בעלי הבטחה, שהם כדאי לסמוך על דבריהם, שעל ידי כן יהיו דבריהם נשמעין: **שנאי בצע.** ששונאין את ממונם בדין כההיא דאמרינן כל דינא דמפקין ממונא מניה בדינא לאו דינא הוא: **שרי אלפים.** הם היו שש מאות שרים לשש מאות אלף: **שרי מאות.** ששת אלפים היו: **שרי חמשים.** שנים עשר אלף: **ושרי עשרת.** ששים אלף:
@22 **ושפטו.** וידונון, לשון צווי: **והקל מעליך.** דבר זה להקל מעליך. והקל, כמו (שמות ח יא) והכבד את לבו, (מלכים ב ג כד) והכות את מואב, לשון הוה:
@23 **וצוך אלהים ויכלת עמד.** המלך בגבורה אם יצוה אותך לעשות כך תוכל עמוד, ואם יעכב על ידך לא תוכל לעמוד: **וגם כל העם הזה.** אהרן נדב ואביהוא ושבעים זקנים הנלוים עתה עמך:
@26 **ושפטו.** ודינין ית עמא: **יביאון.** מיתן: **ישפוטו הם.** כמו ישפוטו וכן (רות ב ח) לא תעבורי, כמו לא תעברי ותרגומו דינין אנון. מקראות העליונים הם לשון צווי, לכך מתרגמין וידונון ייתון, ידונון, ומקראות הללו לשון עשיה:
@27 **וילך לו אל ארצו.** לגיר בני משפחתו:
@28 **ביום הזה.** בראש חדש. לא היה צריך לכתוב אלא ביום ההוא, מהו ביום הזה, שיהיו דברי תורה חדשים עליך כאלו היום נתנו:
@29 **ויסעו מרפידים.** למה הצרך לחזור ולפרש מהיכן נסעו, והלא כבר כתב שברפידים היו חונים, בידוע שמשם נסעו, אלא להקיש נסיעתן מרפידים לביאתן למדבר סיני, מה ביאתן למדבר סיני בתשובה, אף נסיעתן מרפידים בתשובה: **ויחן שם ישראל.** כאיש אחד בלב אחד, אבל שאר כל החניות בתרעומת ובמחלוקת: **נגד ההר.** למזרחו, וכל מקום שאתה מוצא נגד, פנים למזרח:
@30 **ומשה עלה.** ביום השני. וכל עליותיו בהשכמה היו, שנאמר (שמות לד ד) וישכם משה בבקר: **כה תאמר.** בלשון הזה וכסדר הזה: **לבית יעקב.** אלו הנשים, תאמר להן בלשון רכה: **ותגיד לבני ישראל.** ענשין ודקדוקין פרש לזכרים. דברים הקשין כגידין:
@31 **אתם ראיתם.** לא מסרת היא בידכם, ולא בדברים אני משגר לכם, לא בעדים אני מעיד עליכם, אלא אתם ראיתם אשר עשיתי למצרים, על כמה עברות היו חיבין לי קדם שנזדוגו לכם, ולא נפרעתי מהם אלא על ידכם: **ואשא אתכם.** זה יום שבאו ישראל לרעמסס, שהיו ישראל מפזרין בכל ארץ גושן, ולשעה קלה כשבאו לסע ולצאת נקבצו כלם לרעמסס. ואונקלוס תרגם ואשא, ונטלית יתכון, כמו ואסיע אתכם, תקן את הדבר דרך כבוד למעלה: **על כנפי נשרים.** כנשר הנושא גוזליו על כנפיו, שכל שאר העופות נותנים את בניהם בין רגליהם, לפי שמתיראין מעוף אחר שפורח על גביהם, אבל הנשר הזה אינו מתירא אלא מן האדם, שמא יזרוק בו חץ, לפי שאין עוף אחר פורח על גביו, לכך נותנן על כנפיו, אומר מוטב יכנס החץ בי, ולא בבני. אף אני עשיתי כן, (שמות יד יט) ויסע מלאך האלהים וגו' (שם כ) ויבא בין מחנה מצרים וגו' , והיו מצרים זורקים חצים ואבני בליסטראות והענן מקבלם: **ואבא אתכם אלי.** כתרגומו:
@32 **ועתה.** אם עתה תקבלו עליכם יערב לכם מכאן ואלך, שכל התחלות קשות: **ושמרתם את בריתי.** שאכרות עמכם על שמירת התורה: **סגלה.** אוצר חביב, כמו (קהלת ב ח) וסגלת מלכים, כלי יקר ואבנים טובות שהמלכים גונזים אותם. כך אתם תהיו לי סגלה משאר אמות, ולא תאמרו אתם לבדכם שלי ואין לי אחרים עמכם, ומה יש לי עוד שתהא חבתכם נכרת: **כי לי כל הארץ.** והם בעיני ולפני לכלום:
@33 **ואתם תהיו לי ממלכת כהנים.** שרים כמה דאת אמר (שמואל ב' ח יח) ובני דוד כהנים היו: **אלה הדברים.** לא פחות ולא יותר:
@35 **וישב משה את דברי העם** וגו' **.** ביום המחרת, שהוא יום שלישי, שהרי בהשכמה עלה. וכי צריך היה משה להשיב, אלא בא הכתוב ללמדך דרך ארץ ממשה שלא אמר, הואיל ויודע מי ששלחני, איני צריך להשיב:
@36 **בעב הענן.** במעבה הענן וזהו ערפל: **וגם בך.** גם בנביאים הבאים אחריך: **ויגד משה.** ביום המחרת שהוא רביעי לחדש: **את דברי העם** וגו' **.** תשובה על דבר זה שמעתי מהם שרצונם לשמוע ממך אינו דומה השומע מפי השליח לשומע מפי המלך, רצוננו לראות את מלכנו:
@37 **ויאמר ה' אל משה.** אם כן, שמזקיקין לדבר עמם, לך אל העם: **וקדשתם.** וזמנתם, שיכינו עצמם היום ומחר:
@38 **והיו נכנים.** מבדלים מאשה: **ליום השלישי.** שהוא ששה בחדש. ובחמישי בנה משה את המזבח תחת ההר ושתים עשרה מצבה, כל הענין האמור בפרשת ואלה המשפטים, (שמות כד ד) ואין מקדם ומאחר בתורה: **לעיני כל העם.** מלמד שלא היה בהם סומא, שנתרפאו כלם:
@39 **והגבלת.** קבע להם תחומין לסימן, שלא יקרבו מן הגבול והלאה: **לאמר.** הגבול אומר להם, השמרו מעלות מכאן והלאה, ואתה תזהירם על כך: **ונגע בקצהו.** אפלו בקצהו:
@40 **ירה יירה.** מכאן לנסקלין שהם נדחין למטה מבית הסקילה, שהיה גבוה שתי קומות: **יירה.** ישלך למטה לארץ, כמו (שמות טו ד) ירה בים: **במשך היבל.** כשימשוך היובל קול ארוך הוא סימן סלוק שכינה והפסקת הקול, וכיון שנסתלק הם רשאין לעלות: **היבל.** הוא שופר של איל, שכן בערביא קורין לדכרא יובלא, ושופר של אילו של יצחק היה:
@41 **מן ההר אל העם.** מלמד שלא היה משה פונה לעסקיו אלא מן ההר אל העם:
@42 **היו נכנים לשלשת ימים.** לסוף שלשה ימים, הוא יום רביעי שהוסיף משה יום אחד מדעתו, כדברי רבי יוסי, ולדברי האומר בששה בחדש נתנו עשרת הדברות לא הוסיף משה כלום. לשלשת ימים, כמו (פסוק יא) ליום השלישי: **אל תגשו אל אשה.** כל שלשת ימים הללו כדי שיהו הנשים טובלות ליום השלישי ותהיינה טהורות לקבל תורה שאם ישמשו תוך שלשת ימים, שמא תפלוט האשה שכבת זרע לאחר טבילתה ותחזור ותטמא, אבל מששהתה שלושה ימים כבר הזרע מסריח ואינו ראוי להזריע וטהור מלטמא את הפולטת:
@43 **בהית הבקר.** מלמד שהקדים על ידם מה שאין דרך בשר ודם לעשות כן, שיהא הרב ממתין לתלמיד, וכן מצינו ביחזקאל (יחזקאל ג כב) קום צא אל הבקעה וגו' , (שם כג) ואקום ואצא אל הבקעה והנה שם כבוד ה' עומד:
@44 **לקראת האלהים.** מגיד שהשכינה יצאה לקראתם, כחתן היוצא לקראת כלה, וזהו שנאמר (דברים לג ב) ה' מסיני בא, ולא נאמר לסיני בא: **בתחתית ההר.** לפי פשוטו ברגלי ההר. ומדרשו שנתלש ההר ממקומו ונכפה עליהם כגיגית:
@45 **עשן כלו.** אין עשן זה שם דבר, שהרי נקוד השי''ן פת''ח, אלא לשון פעל, כמו אמר, שמר, שמע, לכך תרגומו תנן כליה, ולא תרגם תננא, וכל עשן שבמקרא נקודים קמ''ץ מפני שהם שם דבר: **הכבשן.** של סיד, יכול ככבשן זה ולא יותר, תלמוד לומר (דברים ד יא) בער באש עד לב השמים. ומה תלמוד לומר כבשן, לשבר את האזן, מה שהיא יכולה לשמוע, נותן לבריות סימן הנכר להם. כיוצא בו (הושע יא י) כאריה ישאג, וכי מי נתן כח בארי, אלא הוא, והכתוב מושלו כאריה, אלא אנו מכנין ומדמין אותו לבריותיו, כדי לשבר את האזן מה שיכולה לשמוע. וכיוצא בו (יחזקאל מג ב) וקולו כקול מים רבים, וכי מי נתן קול למים, אלא הוא, ואתה מכנה אותו לדמותו לבריותיו, כדי לשבר את האזן:
@46 **הולך וחזק מאד.** מנהג הדיוט, כל זמן שהוא מאריך לתקע קולו מחליש וכוהה, אבל כאן הולך וחזק מאד. ולמה כך, מתחלה לשבר אזניהם מה שיכולין לשמוע: **משה ידבר.** כשהיה משה מדבר ומשמיע הדברות לישראל שהרי לא שמעו מפי הגבורה אלא (שמות כ ב) אנכי ולא יהיה לך והקדוש ברוך הוא מסיעו לתת בו כח להיות קולו מגביר ונשמע: **יעננו בקול.** יעננו על דבר הקול, כמו (מלכים א' יח כד) אשר יענה באש, על דבר האש להורידו:
@47 **וירד ה' על הר סיני.** יכול ירד עליו ממש, תלמוד לומר (שמות כ יט) כי מן השמים דברתי עמכם. מלמד שהרכין שמים העליונים והתחתונים והציען על גבי ההר, כמצע על המטה, וירד כסא הכבוד עליהם:
@48 **העד בעם.** התרה בהם שלא לעלות בהר: **פן יהרסו** וגו' **.** שלא יהרסו את מצבם על ידי שתאותם אל ה' לראות ויקרבו לצד ההר: **ונפל ממנו רב.** כל מה שיפול מהם ואפלו הוא יחידי חשוב לפני רב: **יהרסו.** כל הריסה מפרדת אסיפת הבנין, אף הנפרדין ממצב אנשים הורסים את המצב:
@49 **וגם הכהנים.** אף הבכורות שהעבודה בהם: **הנגשים אל ה'.** להקריב קרבנות, אף הם אל יסמכו על חשיבותם לעלות: **יתקדשו.** יהיו מזמנים להתיצב על עמדם: **פן יפרץ.** לשון פרצה, יהרוג בהם ויעשה בהם פרצה:
@50 **לא יוכל העם.** איני צריך להעיד בהם שהרי מתרין ועומדין הם היום שלשת ימים, ולא יוכלו לעלות שאין להם רשות:
@51 **לך רד.** והעד בהם שנית, שמזרזין את האדם קדם מעשה, וחוזרין ומזרזין אותו בשעת מעשה: **ועלית אתה ואהרן עמך והכהנים.** יכול אף הם עמך, תלמוד לומר ועלית אתה. אמור מעתה, אתה מחצה לעצמך ואהרן מחצה לעצמו והם מחצה לעצמם. משה נגש יותר מאהרן, ואהרן יותר מן הכהנים, והעם כל עיקר אל יהרסו את מצבם לעלות אל ה': **פן יפרץ בם.** אף על פי שהוא נקוד חטף קמ''ץ אינו זז מגזרתו, כך דרך כל תבה שנקדתה מלאפו''ם כשהיא סמוכה במקף משתנה הנקוד לחטף קמ''ץ:
@52 **ויאמר אליהם.** התראה זו:
@53 **וידבר אלהים.** אין אלהים אלא דין. לפי שיש פרשיות בתורה שאם עשאן אדם מקבל שכר, ואם לאו אינו מקבל עליהם פרענות, יכול אף עשרת הדברות כן, תלמוד לומר וידבר אלהים, דיין לפרע: **את כל הדברים האלה.** מלמד שאמר הקדוש ברוך הוא עשרת הדברות בדבור אחד, מה שאי אפשר לאדם לומר כן. אם כן מה תלמוד לומר עוד אנכי ולא יהיה לך, שחזר ופרש על כל דבור ודבור בפני עצמו: **לאמר.** מלמד שהיו עונין על הן הן ועל לאו לאו:
@54 **אשר הוצאתיך מארץ מצרים.** כדאי היא ההוצאה שתהיו משעבדים לי. דבר אחר לפי שנגלה בים כגבור מלחמה, ונגלה כאן כזקן מלא רחמים, שנאמר (שמות כד י) ויראו את אלהי ישראל ותחת רגליו כמעשה לבנת הספיר, זו היתה לפניו בשעת השעבוד, (שם) וכעצם השמים, משנגאלו, הואיל ואני משתנה במראות אל תאמרו שתי רשויות הן, אנכי הוא אשר הוצאתיך ממצרים ועל הים. דבר אחר לפי שהיו שומעין קולות הרבה, שנאמר, (להלן פסוק טו) את הקולות, קולות באין מארבע רוחות ומן השמים ומן הארץ, אל תאמרו רשויות הרבה הן. ולמה אמר לשון יחיד, אלהיך, לתן פתחון פה למשה ללמד סנגוריא במעשה העגל, וזהו שאמר (שמות לב יא) למה ה' יחרה אפך בעמך, לא להם צוית, לא יהיה לכם אלהים אחרים, אלא לי לבדי: **מבית עבדים.** מבית פרעה שהייתם עבדים לו. או אינו אומר אלא מבית עבדים, שהיו עבדים לעבדים, תלמוד לומר (דברים ז ח) ויפדך מבית עבדים מיד פרעה מלך מצרים, אמור מעתה עבדים למלך היו, ולא עבדים לעבדים:
@55 **לא יהיה לך.** למה נאמר, לפי שנאמר (פסוק ד) לא תעשה לך, אין לי אלא שלא יעשה, העשוי כבר מנין שלא יקים, תלמוד לומר לא יהיה לך: **אלהים אחרים.** שאינן אלהות אלא אחרים עשאום אלהים עליהם, ולא יתכן לפרש אלהים אחרים זולתי, שגנאי הוא כלפי מעלה לקרותם אלהות אצלו. דבר אחר אלהים אחרים, שהם אחרים לעובדיהם, צועקים אליהם ואינן עונין אותם, ודומה כאלו הוא אחר שאינו מכירו מעולם: **על פני.** כל זמן שאני קים, שלא תאמר לא נצטוו על עבודה זרה אלא אותו הדור:
@56 **פסל.** על שם שנפסל: **וכל תמונה.** תמונת כל דבר אשר בשמים:
@57 **אל קנא.** מקנא לפרע ואינו עובר על מדתו למחול על עוון עבודה זרה, כל לשון קנא אינפרינמינ''ט בלעז , נותן לב לפרע: **לשנאי.** כתרגומו, כשאוחזין מעשה אבותיהם בידיהם:
@58 **ועשה חסד.** נוצר חסד שאדם עושה, לשלם שכר עד לאלפים דור, נמצאת מדה טובה יתרה על מדת פרענות אחת על חמש מאות, שזו לארבעה דורות וזו לאלפים:
@59 **לשוא.** (השני לשון שקר כתרגומו) כמא דתימר (שבועות כט א) אי זהו שבועת שוא, נשבע לשנות את הידוע, על עמוד של אבן שהוא של זהב. (הראשון לשון מגן, כתרגומו) זה הנשבע לחנם ולהבל, על של עץ עץ ועל אבן אבן:
@60 **זכור.** זכור ושמור בדבור אחד נאמרו. וכן (שמות לא יד) מחלליה מות יומת, (במדבר כח ט) וביום השבת שני כבשים, וכן (דברים כב יא) לא תלבש שעטנז, (שם יב) גדילים תעשה לך, וכן (ויקרא יח טז) ערות אשת אחיך, (דברים כה ה) יבמה יבא עליה, הוא שנאמר (תהלים סב יב) אחת דבר אלהים שתים זו שמעתי. זכור לשון פעול הוא, כמו (ישעיה כב יג) אכול ושתו, (שמואל ב ג טז) הלוך ובכה, וכן פתרונו תנו לב לזכור תמיד את יום השבת, שאם נזדמן לך חפץ יפה תהא מזמינו לשבת:
@61 **ועשית כל מלאכתך.** כשתבא שבת, יהא בעיניך כאלו מלאכתך עשויה, שלא תהרהר אחר מלאכה:
@62 **אתה ובנך ובתך.** אלו קטנים. או אינו אלא גדולים, אמרת הרי כבר מזהרים הם, אלא לא בא אלא להזהיר גדולים על שביתת הקטנים, וזו ששנינו (שבת קכא א) קטן שבא לכבות אין שומעין לו, מפני ששביתתו עליך:
@63 **וינח ביום השביעי.** כביכול הכתיב בעצמו מנוחה ללמד המנו קל וחמר לאדם, שמלאכתו בעמל וביגיעה, שיהא נח בשבת: **ברך ויקדשהו.** ברכו במן לכפלו בששי לחם משנה, וקדשו במן שלא היה יורד בו:
@64 **למען יאריכון ימיך.** אם תכבד יאריכון, ואם לאו יקצרון, שדברי תורה נוטריקון הם נדרשין מכלל הן לאו ומכלל לאו הן:
@65 **לא תנאף.** אין ניאוף אלא באשת איש, שנאמר (ויקרא כ י) מות יומת הנואף והנואפת, ואומר (יחזקאל טז לב) האשה המנאפת תחת אישה תקח את זרים: **לא תגנב.** בגונב נפשות הכתוב מדבר. לא תגנבו (ויקרא יט יא) בגונב ממון. או אינו אלא זה בגונב ממון, ולהלן בגונב נפשות, אמרת דבר הלמד מענינו, מה לא תרצח, לא תנאף, מדבר בדבר שחייבין עליהם מיתת בית דין, אף לא תגנוב דבר שחיב עליו מיתת בית דין:
@67 **וכל העם ראים.** מלמד שלא היה בהם אחד סומא. ומנין שלא היה בהם אלם, תלמוד לומר (שמות יט ח) ויענו כל העם. ומנין שלא היה בהם חרש, תלמוד לומר (שמות כד ז) נעשה ונשמע: **ראים את הקולות.** רואין את הנשמע, שאי אפשר לראות במקום אחר: **את הקולת.** (מכילתא בחדש פ''ט) היוצאין מפי הגבורה: **וינעו.** (שם) אין נוע אלא זיע: **ויעמדו מרחק.** היו נרתעין לאחוריהם שנים עשר מיל כאורך מחניהם ומלאכי השרת באין ומסיעין אותן להחזירם, שנאמר (תהלים סח יג) מלכי צבאות ידדון ידדון:
@69 **לבעבור נסות אתכם.** לגדל אתכם בעולם שיצא לכם שם באמות שהוא בכבודו נגלה עליכם: **נסות.** לשון הרמה וגדלה, כמו (ישעיה סב י) הרימו נס, ארים נסי (ישעיה מט כב) , וכנס על הגבעה (ישעיה ל, יז) , שהוא זקוף: **ובעבור תהיה יראתו.** על ידי שראיתם אותו יראוי ומאים, תדעו כי אין זולתו ותיראו מפניו:
@70 **נגש אל הערפל.** לפנים משלש מחיצות, חשך ענן וערפל שנאמר (דברים ד יא) וההר בוער באש עד לב השמים חשך ענן וערפל, ערפל הוא עב הענן, שנאמר לו (שמות יט ט) הנה אנכי בא אליך בעב הענן:
@71 **כה תאמר.** בלשון הזה: **אתם ראיתם.** יש הפרש בין מה שאדם רואה למה שאחרים משיחין לו, שמה שאחרים משיחין לו פעמים שלבו חלוק מלהאמין: **כי מן השמים דברתי.** וכתוב אחד אומר וירד ה' על הר סיני, בא הכתוב השלישי והכריע ביניהם (דברים ד לו) מן השמים השמיעך את קולו ליסרך ועל הארץ הראך את אשו הגדולה, כבודו בשמים ואשו וגבורתו על הארץ. דבר אחר הרכין שמים ושמי השמים והציען על ההר, וכן הוא אומר (תהלים יח י) ויט שמים וירד:
@72 **לא תעשון אתי.** לא תעשון דמות שמשי המשמשים לפני במרום: **אלהי כסף.** בא להזהיר על הכרובים, שאתה עושה לעמוד אתי, שלא יהיו של כסף, שאם שניתם לעשותם של כסף הרי הן לפני כאלהות: **ואלהי זהב.** בא להזהיר שלא יוסיף על שנים, שאם עשית ארבעה, הרי הן לפני כאלהי זהב: **לא תעשו לכם.** לא תאמר הריני עושה כרובים בבתי כנסיות ובבתי מדרשות כדרך שאני עושה בבית עולמים, לכך נאמר לא תעשו לכם:
@73 **מזבח אדמה.** מחבר באדמה, שלא יבננו על גבי עמודים או על גבי כפים. דבר אחר שהיה ממלא את חלל מזבח הנחשת אדמה בשעת חניתן: **תעשה לי.** שתהא תחלת עשייתו לשמי: **וזבחת עליו.** אצלו, כמו (במדבר ב כ) ועליו מטה מנשה. או אינו אלא עליו ממש, תלמוד לומר (דברים יב כז) הבשר והדם על מזבח ה' אלהיך, ואין שחיטה בראש המזבח: **את עלתיך ואת שלמיך.** אשר מצאנך ומבקרך. את צאנך ואת בקרך, פרוש לאת עולתיך ואת שלמיך: **בכל המקום אשר אזכיר את שמי.** אשר אתן לך רשות להזכיר שם המפרש שלי, שם אבא אליך וברכתיך אשרה שכינתי עליך מכאן אתה למד שלא נתן רשות להזכיר שם המפרש אלא במקום שהשכינה באה שם, וזהו בית הבחירה. שם נתן רשות לכהנים להזכיר שם המפרש בנשיאת כפים לברך את העם:
@74 **ואם מזבח אבנים.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה ואם מזבח אבנים תעשה לי, הרי אם זה משמש בלשון כאשר, כאשר תעשה לי מזבח אבנים לא תבנה אתהן גזית שהרי חובה עליך לבנות מזבח אבנים, שנאמר (דברים כז ו) אבנים שלמות תבנה, וכן (שמות כב כד) אם כסף תלוה, חובה הוא, שנאמר (דברים טו ח) והעבט תעביטנו. ואף זה משמש בלשון כאשר וכן (ויקרא ב יד) ואם תקריב מנחת בכורים זו מנחת העמר, שהיא חובה, ועל כרחך אין אם הללו תלוין, אלא ודאין, ובלשון כאשר הם משמשים: **גזית.** לשון גזיזה שפוסלן ומסתתן בברזל: **כי חרבך הנפת עליה.** הרי כי זה משמש בלשון פן, שהוא דילמא, פן תניף חרבך עליה: **ותחללה.** הא למדת, שאם הנפת עליה ברזל חללת, שהמזבח נברא להאריך ימיו של אדם, והברזל נברא לקצר ימיו של אדם, אין זה בדין, שיונף המקצר על המאריך. ועוד, שהמזבח מטיל שלום בין ישראל לאביהם שבשמים, לפיכך לא יבא עליו כורת ומחבל. והרי דברים קל וחמר ומה אבנים שאינם רואות ולא שומעות ולא מדברות על ידי שמטילות שלום אמרה תורה לא תניף עליהם ברזל, המטיל שלום בין איש לאשתו, בין משפחה למשפחה, בין אדם לחברו, על אחת כמה וכמה שלא תבואהו פרענות:
@75 **ולא תעלה במעלות.** כשאתה בונה כבש למזבח, לא תעשהו מעלות מעלות אישיקלונ''ש בלעז [מדרגות] אלא חלק יהא ומשופע: **אשר לא תגלה ערותך.** שעל ידי המעלות אתה צריך להרחיב פסיעותיך, ואף על פי שאינו גלוי ערוה ממש, שהרי כתיב (שמות כח מב) ועשה להם מכנסי בד, מכל מקום הרחבת הפסיעות קרוב לגלוי ערוה הוא, ואתה נוהג בהם מנהג בזיון. והרי דברים קל וחומר ומה אבנים הללו שאין בהם דעת להקפיד על בזיונן אמרה תורה הואיל ויש בהם צורך, לא תנהג בהם מנהג בזיון, חברך שהוא בדמות יוצרך, ומקפיד על בזיונו, על אחת כמה וכמה:

@1 **כבר** נחלקו רבותינו (מכילתא כאן, זבחים קטז.) בפרשה הזאת. יש מהם אומרים כי קודם מתן תורה בא יתרו כסדר הפרשיות, ויש מהן שאמרו שאחר מתן תורה בא. וזה ודאי יסתייע מן הכתוב (פסוק ה) שאמר **ויבא יתרו חתן משה ובניו ואשתו אל משה אל המדבר אשר הוא חונה שם הר האלהים** . הנה אמר שבא אליו בחנותו לפני הר סיני שחנו שם שנה אחת, וזה טעם **אשר הוא חונה שם** . ועוד, שאמר **והודעתי את חוקי האלהים ואת תורותיו** (פסוק טז), שהם הנתונים לו בהר סיני. ועוד, כי כאן (פסוק כז) אמר **וישלח משה את חותנו וילך לו אל ארצו** , והיה זה בשנה השניה בנסעם מהר סיני, כמו שאמר בפרשת בהעלותך (במדבר י כט) ויאמר משה לחובב בן רעואל המדיני חותן משה נוסעים אנחנו, ושם כתוב (פסוק ל) ויאמר אליו לא אלך כי אם אל ארצי ואל מולדתי אלך, והיא ההליכה הכתובה בכאן וילך לו אל ארצו (להלן פסוק כז):
@1 **ועוד** הביאו ראיה ממה שאמר הכתוב (דברים א ו ז) ה' אלהינו דבר אלינו בחורב לאמר רב לכם שבת בהר הזה פנו וסעו לכם, ושם (בפסוק ט) נאמר ואומר אליכם בעת ההיא לאמר לא אוכל לבדי שאת אתכם, ואקח את ראשי שבטיכם אנשים חכמים וגו' (שם טו), וזו עצת יתרו, ושם (בפסוק יט) כתוב ונסע מחורב, כי נסעו מיד. ואם כן נצטרך טעם למה מקדים הפרשה הזאת לכותבה בכאן:
@1 **ואמר** ר''א כי היה זה בעבור דבר עמלק, כי כאשר הזכיר הרעה שעשה עמנו עמלק וצוה שנגמלהו כרעתו, הזכיר שעשה לנו יתרו טובה, להורותינו שנשלם לו גמול טוב, וכשנבא להכרית את עמלק כמצוה עלינו שנזהר בבני הקיני העומדים עמהם ולא נוסיפם עמם. הוא דבר שאול שאמר להם כן (ש''א טו ו):
@1 **ועם** כל זה אני שואל, על הדעת הזו כשאמר הכתוב **וישמע יתרו כל אשר עשה ה' למשה ולישראל עמו כי הוציא ה' את ישראל ממצרים** , ולמה לא אמר ששמע מה שעשה למשה ולישראל במתן התורה שהוא מהנפלאות הגדולות שנעשו להם, כמו שאמר (דברים ד לב) כי שאל נא לימים ראשונים אשר היו לפניך למן היום אשר ברא אלהים אדם על הארץ ולמקצה השמים ועד קצה השמים הנהיה כדבר הגדול הזה או הנשמע כמוהו, השמע עם קול אלהים מדבר מתוך האש כאשר שמעת אתה ויחי:
@1 **וכשאמר ויספר משה לחותנו את כל אשר עשה ה' לפרעה ולמצרים על אודות ישראל את כל התלאה אשר מצאתם בדרך** (פסוק ח), ואמר יתרו מזה עתה ידעתי כי גדול ה' (פסוק יא), למה לא ספר לו מעמד הר סיני, וממנו יודע כי השם אמת ותורתו אמת ואין עוד מלבדו, כמו שאמר (דברים ד לה לו) אתה הראת לדעת כי ה' הוא האלהים אין עוד מלבדו, מן השמים השמיעך את קולו וגו'. ואולי נאמר ששמע יתרו בארצו מיד כי הוציא ה' את ישראל ממצרים ונסע מארצו והגיע אל משה אחרי היותו חונה בהר סיני אחר מתן תורה. ולא סיפר שהזכיר לו ענין המעמד ההוא, כי הדבר עודנו קרוב ועודם שם, ובידוע כי סופר לו:
@1 **והקרוב** אלי לתפוש סדר התורה שבא קודם מתן תורה בהיותם ברפידים, כמו שאמרו במכילתא (כאן) רבי יהושע אומר מלחמת עמלק שמע ובא, שהיא כתובה בצדו, ונסע עמהם מרפידים אל הר סיני. והכתוב (פסוק ה) שאמר אל המדבר אשר הוא חונה שם הר האלהים, ענינו כי היה הר סיני בדרך מדין קרוב משם, שהרי משה הלך שם לרעות צאן מדין (לעיל ג א), ובאהרן אמר ויפגשהו בהר האלהים (שם ד כז). והנה יתרו יצא עם בתו והבנים ממדין ובאו אל הר סיני, ומשה היה ברפידים שהוא מקום אחד במדבר סין, שהכתוב אמר (לעיל טז א) ויסעו מאלים ויבואו כל עדת בני ישראל אל מדבר סין אשר בין אלים ובין סיני, לומר כי מדבר סין מגיע עד הר סיני, ויכלול דפקה אלוש ורפידים. ואף על פי שאמר (לעיל יז א) ויסעו ממדבר סין ויחנו ברפידים, כך אמר ויסעו ממדבר סין ויחנו בדפקה ואלוש (במדבר לג יב יג), והם ממדבר סין עצמו, כי המדבר כלו יקרא מדבר סין, והמקום שלפני הר סיני יקרא מדבר סין, וכמוהו וישובו אל ארץ פלשתים (בראשית כא לב):
@1 **והנה** יהיה פירוש הכתוב **ויבא יתרו חותן משה ובניו ואשתו אל משה אל המדבר אשר הוא חונה שם ויבא אל הר האלהים** , כי אל ההר בא ושם עמד, והוא כמו שאמר ויבא אל הר האלהים חורבה, וכן ויפגשהו בהר האלהים (לעיל ד כז), וכן רב לכם שבת בהר הזה (שם ד כז). ומן ההר שלח אליו **אני חותנך יתרו בא אליך** , **ויצא אליו משה** . ולא נצטרך לומר כי ''ויאמר'' יהיה מוקדם. ואפילו אם לא יהיה רפידים במדבר סין, על כל פנים במדבר הוא, כי לא באו ישראל בארץ נושבת כל ארבעים שנה, וקרוב מהר סיני היה, שבאו משם אל ההר ביום אחד מחנה קהל גדול כמוהו, וכמו שנתבאר (לעיל יז ו) בענין הצור ששתו ממנו ברפידים כאשר פירשתי (שם). והנה יהיה הפירוש שאמרתי נכון:
@1 **וראיתי** נמי במכילתא (כאן) **אל המדבר אשר הוא חונה שם** , הרי הכתוב מתמיה עליו שהוא שרוי בתוך כבודו של עולם ובקש לצאת אל המדבר תוהו שאין בו כלום. דעתם לפרש **אל המדבר אשר הוא חונה שם** , הוא מדבר **הר האלהים** , כי מאלים ועד הר סיני היה מדבר סין, וספר הכתוב שבא **אל קצה המדבר אשר הוא חונה שם** , **הוא מדבר הר האלהים חורבה** . והזכיר זה לשבח יתרו, שעזב ארצו ובא אל המדבר אשר הוא שם בעבור שידע שהוא הר האלהים, כי בו נגלו אליו האלהים, שכבר שמע כל הענין כי ישראל יצאו ממצרים לעבוד את האלהים על ההר הזה (לעיל ג יב), ובא לשם ה' אלהי ישראל. וגם זה נכון הוא:
@1 **וכן** נראה לי שאמר כאן (בפסוק כז) וישלח משה את חותנו וילך לו אל ארצו, שהיה זה בשנה הראשונה, והלך לו אל ארצו וחזר אליו. ויתכן שהלך שם לגייר את משפחתו וחזר למשה ועודנו בהר סיני כי קרוב הוא למדין, כמו שהזכרתי, שהרי בנסוע המחנה באייר בשנה שנייה כשאמר לו משה נוסעים אנחנו לכה אתנו (במדבר י כט), וענה אותו לא אלך כי אם אל ארצי ואל מולדתי אלך (שם ל), התחנן לו משה מאד ואמר לו אל נא תעזוב אותנו וגו' והיית לנו לעינים, והיה כי תלך עמנו והיה הטוב ההוא אשר ייטיב ה' עמנו והטבנו לך (שם לא לב), ולא השיב אותו דבר, ונראה שקבל דבריו ועשה כרצונו ולא עזבם:
@1 **אבל** בימי שאול היו בניו עם עמלק ובאו והתחברו עוד אל ישראל, והיו בירושלם בני יונדב בן רכב, אולי במות משה חזר לארצו הוא או בניו. ואפשר שהיה הקני היושב עם עמלק ממשפחת יתרו לא בניו, ועשה חסד עם כל המשפחה בעבורו כאשר עשה יהושע עם משפחת רחב (יהושע ו כג):
@1 **ודעת** רבותינו כך היא שהלך עמהם, אמרו בספרי (בהעלותך לד א) שנתנו לו דשנה של יריחו והיו אוכלין אותה עד שנבנה בית המקדש ת''מ שנה, ורש''י עצמו כתב זה בסדר בהעלותך (במדבר י לב). אם כן חזר אליו. ובמכילתא (כאן) אמר לו הריני הולך ומגייר את בני מדינתי שאביאם תחת כנפי שמים, יכול שהלך ולא חזר, ת''ל ובני קיני חותן משה עלו מעיר התמרים וכו':
@1 **למשה ולישראל עמו** . הנפלאות שעשה למשה, שעשה עמו חסד וטובה שיבא אל פרעה תמיד ולא יפחד ממנו ויביא עליו המכות עד שיצאו ממצרים הוא והעם עמו, והוא כמלך עליהם. ור''א אמר, **למשה ולישראל** , בעבור משה וישראל, והטעם על המכות וטביעת פרעה. וכן נראה מדעת רבותינו שאמרו (במכילתא כאן) שקול משה כישראל וישראל כמשה:
@1 וטעם **אשר עשה אלהים** , **כי הוציא ה'** . הזכיר אלהים, השם שהיה יתרו יודע מלפנים, וכי הוציא ה', בשמו הגדול, שנודע עתה על ידי משה שבו נעשו האותות:
@2 **אחר שלוחיה** . בעבור שהזכיר הכתוב (לעיל ד כ) ויקח משה את אשתו ואת בניו וישב ארצה מצרים, הוצרך לומר כאן שהיתה בבית אביה, כי משה שלחה שם. ויתכן שיאמר כי לקחה יתרו להשיבה אליו אע''פ ששלחה ממנו, בעבור ששמע כל אשר עשה אלהים למשה, כי מעתה ראוי ללכת אחרי המלך בכל אשר ילך:
@3 **ואת שני בניה אשר שם האחד גרשום** . אף על פי שאין זה מקום מולדתם יפרש שם הבנים, כי לא היה מקום להזכיר שם אליעזר בהולדו כאשר פירשתי בסדר ואלה שמות (ד כ). ובכאן רצה להזכיר החסד שעשה הקדוש ברוך הוא למשה, שהיה גר בארץ נכריה, ונותן שם הודאה לשם שהצילו מחרב פרעה בברחו, ועתה הוא מלך על ישראל והטביע פרעה ועמו בים. וטעם **כי אמר** , נמשך למשה הנזכר בפסוק הראשון, וכן **שם האחד אליעזר כי אלהי אבי בעזרי** , נמשך על כי אמר, וכן רבים:
@6 **ויאמר אל משה אני חותנך יתרו בא אליך** . שלח לו הדבר באגרת כתוב בה כן, כי השליח לא יאמר אני חותנך, אבל יאמר **הנה חותנך יתרו בא אליך** . וכן לא יתכן שיאמר לו ככה פה אל פה, כי יאמר הנה באתי אליך, ואין דרך להזכיר שמו אני פלוני, כי בראותו אותו יכירנו, וכמהו ויאמר חירם מלך צר בכתב וישלח אל שלמה (דהי''ב ב י):
@10 **אשר הציל אתכם מיד מצרים ומיד פרעה** . כי עשה עמכם נס גדול שלא הרגו אתכם פרעה ועמו, כי באו בעבורכם עליהם מכות גדולות בארצם. והיה הנס הזה גדול במשה, על כן הזכירו לנכח בכלל, ואמר ''אתכם'', אתה והעם. ועוד נס אחר, **אשר הציל את העם מתחת יד מצרים** , שהיו הם במצרים ויצאו משם לחירות עולם. ור''א אמר כי ברך תחלה השם אשר הציל אתכם אתה ואהרן שבאו המכות על ידכם לפרעה ולמצרים, ואחרי כן ברך **אשר הציל את העם מתחת יד מצרים** במצרים ובים:
@11 **כי בדבר אשר זדו עליהם** . פירושו בדבר אשר הזידו המצרים על ישראל ידעתי שהוא גדול מכל האלהים. וטעם זה, מפני שהשם גזר על ישראל ועבדום וענו אותם (בראשית טו יג) ולא היה על המצרים בזה העונש הגדול, אבל הזידו עליהם וחשבו להכרית אותם מן העולם, כמו שאמר (לעיל א י) הבה נתחכמה לו פן ירבה, וצוה למילדות להמית הבנים, וגזר עליהם כל הבן הילוד היאורה תשליכהו (שם כב), ומפני זה היה עליהם העונש המשחית אותם לגמרי, וזהו שאמר וגם את הגוי אשר יעבודו דן אנכי (בראשית טו יד), כמו שפרשתיו (שם ולעיל יב מב). והנה השם ראה מחשבתם, ונקם מהם על זדון לבם. וכן אמר הכתוב עוד כי ידעת כי הזידו עליהם (נחמיה ט י), כי העונש בעבור הזדון שחשבו לעשות להם. והנה ה' רואה ללב ועושה משפט העשוקים, ונוקם ובעל חמה, ואין מוחה בידו. ואונקלוס שאמר ארי בפתגמא דחשיבו מצראי למידן ית ישראל ביה דנינון, ירצה לומר כי היה ענשם על טביעת הילדים ביאור שאיננו בכלל ועבדום וענו אותם, ועל כן אבדם במים:
@12 **ויקח יתרו חתן משה עולה וזבחים לאלהים** . היה כל זה טרם בואם אל הר סיני. גם יתכן לפרש שסידר הכתוב כל ענין יתרו, אבל היה זה אחר שעמד עמהם ימים רבים, ונתגייר במילה וטבילה והרצאת דמים כמשפט:
@12 **ויבא אהרן וכל זקני ישראל לאכל לחם** . עמו ביום חתונתו כי חתן דמים הוא:
@13 **ויהי ממחרת** . ממחרת היום שעשו זה שנזכר **ישב משה לשפוט את העם** . ואמרו במכילתא (כאן) ממחרת יום הכפורים. ואין דעתם לומר שיהיה ממחרת רמז ליום הכפורים, כי יום הכפורים לא נזכר בכתוב שיאמר עליו ממחרת. וגם כן אין הכונה שיהיה ממחרתו ממש, כי לא אכלו ביום הכפורים, אם היה להם יום הכפורים בשנה ראשונה קודם שנצטוו בו. ועוד, כי בו ביום הכפורים נתנו לוחות אחרונות וממחרתו ירד משה ודבר עם בני ישראל ויצום את כל אשר דבר השם אתו בהר סיני (להלן לד לב), ואיננו יום המשפט שיעמוד העם עליו מן הבקר עד ערב. וגם כן אי אפשר שיהיה בשנה שניה ביום הכפורים, כי בנסוע הדגלים אמר כי אם אל ארצי ואל מולדתי אלך (במדבר י ל). אבל הכוונה לברייתא הזו לומר שהיה זה אחר יום הכפורים, כי אין להם יום פנוי למשפט מיום בואם להר סיני עד אחר יום הכפורים של שנה ראשונה הזאת:
@13 **ואמר עולה וזבחים לאלהים** , בעבור שיתרו עדיין לא ידע ה', כי משה אמר **אשר עשה ה' לפרעה** :
@13 **ולמצרים וגו' ויצילם ה'** (לעיל פסוק ח), אבל יתרו הקריב לאלהים. וככה לא ימצא בכל הקרבנות שבתורת כהנים, כאשר אפרש בע''ה (ויקרא א ט). וכן כי **יבא אלי העם לדרוש אלהים** , **והודעתי את חקי האלהים** (להלן פסוק טו~טז), דברי משה לחמיו. ויתכן שאמר לו כן בעבור; **כי המשפט לאלהים הוא** (דברים א יז), כמו שמזכירין רבותינו תמיד אלהים זו מדת הדין (בר''ר עג ג):
@15 **כי יבא אלי העם לדרוש אלהים** . השיב משה לחותנו צריכים הם שיעמדו עלי זמן גדול מן היום, כי לדברים רבים באים לפני, כי יבא אלי העם לדרוש אלהים להתפלל על חוליהם ולהודיעם מה שיאבד להם, כי זה יקרא ''דרישת אלהים'', וכן יעשו עם הנביאים כמו שאמר (ש''א ט ט) לפנים בישראל כה אמר האיש בלכתו לדרוש אלהים לכו ונלכה עד הרואה, וכן ודרשת את ה' מאותו לאמר האחיה מחלי זה (מ''ב ח ח), שיתפלל עליו ויודיענו אם נשמעה תפלתו, וכן ותלך לדרוש את ה' (בראשית כה כב), כמו שפירשתי שם, ועוד שאני שופט אותם, **כי יהיה להם דבר בא אלי ושפטתי** . ועוד אני מלמד אותם תורה, **והודעתי להם את חקי האלהים ואת תורותיו** :
@19 **ויהי אלהים עמך** . בעצה זו, אמר לו צא המלך בגבורה. לשון רש''י. ור''א פירש שמע בקולי והיה ה' בעזרך להצליחך בעצתי. אבל למטה (בפסוק כג) אמר **אם את הדבר הזה תעשה וצוך אלהים** , שפירושו אם תעשה את הדבר וצוך אלהים לעשותו אז תוכל לעמוד, שתמלך בגבורה, ואין ספק שעשה כן:
@19 **היה אתה לעם מול האלהים** . נגד האלהים, ויאמר היה אתה בעבורם עומד נגד האלהים להתפלל אליו, כטעם יום צעקתי בלילה נגדך (תהלים פח ב):
@19 **והבאת אתה את הדברים** . שיבקשו **אל האלהים** . הודה לו על הדבר הראשון שאמר **כי יבא אלי העם לדרוש אלהים** . ויתכן שהיה גם בזה עצה ממנו, יאמר **היה אתה לעם מול האלהים** לשבת באהל מועד מזומן לפניו לדרוש אותו, ולא יהיה זה במקום המשפט:
@20 **והזהרת אתהם את החקים ואת התורות** . ותודיע להם את הדרך אשר ילכו בה על פי התורה והמצוה. שתזהירם אתה מאד, ותלמדם התורה והמצוה. הודה לו גם במה שאמר **והודעתי את חקי האלהים ואת תורותיו** . וגם בזה עצה, להזהיר אותם מאד, ולהתרות אותם במצות ועונשם, אחרי אשר לא יעשה הוא בהם את הדין. אבל במשפט אשר אמרת **ושפטתי בין איש ובין רעהו** , שים לך שופטים עמך, כי כבד ממך דבר המשפט יותר מן הכל, וטוב לך ולהם להקל מעליך, **ונשאו אתך** . ובידוע כי היו עם משה שוטרים נוגשים בעם, להביא הנתבעים לפניו ולנגשם בדבר המשפט, והרבה מהם עם השופטים האלו, ולכך אמר במשנה תורה (דברים א טו) ושוטרים לשבטיכם. ואין צריך להזכיר זה בכאן, כי לא היה מעצת יתרו:
@20 (כא~כג) וטעם **אנשי חיל** . אנשים ראויים להנהיג עם גדול, כי כל קבוץ ואוסף יקרא חיל, ואיננו ביוצאי צבא המלחמה בלבד, וכן חיל גדול מאד (יחזקאל לג ו), ובאר בה, חילי הגדול (יואל ב כה), ובממון, כחי ועוצם ידי עשה לי את החיל הזה (דברים ח יז), ישאו על כתף עירים חיליהם (ישעיה ל ו), ובפירות, תאנה וגפן נתנו חילם (יואל ב כב). והנה יקרא איש חיל במשפטים, החכם הזריז והישר. ובמלחמה. הגבור הזריז היודע מערכות המלחמה, ותקרא גם כן האשה אשת חיל (משלי לא י) בהיותה זריזה ויודעת בהנהגת הבית:
@20 **והנה** יתרו דבר בכלל ופרט, אמר שיחזה אנשים ראויים להנהיג העם הגדול במשפטים, ופרט, שיהו **יראי אלהים אנשי אמת ושונאי בצע** , כי לא יהיו אנשי חיל במשפט בלי מדות הללו. ולא הוצרך להזכיר חכמתם ובינתם, כי הדבר ברור שהוא בכלל אנשי חיל. וכאשר נאמר למטה **ויבחר משה אנשי חיל** , הנה הכל בכלל, שהיו **יראי אלהים אנשי אמת שונאי בצע וחכמים ונבונים** . ועוד, שאמר **מכל ישראל** , וטעמו המובחר **מכל ישראל** , והם שיש בהם כל המדות הללו, כי כיון שאמר **מכל ישראל** , אמר שהיו המובחרים מכלם, בידוע כי הטובים שבישראל כל מדות טובות בהם, אבל יתרו מפני שלא היה רגיל בעם הוצרך לפרש:
@20 **ויש** מפרשים אנשי חיל, אנשי כח וזריזות, וכן אשת חיל, בעלת כח וזריזות בעבודת הבית, כאשר יפרש בה (במשלי לא), כענין ואשר כח בהם לעמוד בהיכל המלך (דניאל א ד), וכן הניעמו בחילך (תהלים נט יב), בכחך. וכן וברב חילו לא ימלט (שם לג יז), מלשון הארמית שיאמר ביש לאל ידי (בראשית לא כט) אית חילא בידי. ולמטה (בפסוק כה) אמר **ויבחר משה אנשי חיל מכל ישראל** , המובחרים מכל העם, והכל בכלל, כאשר פירשתי:
@20 **שונאי בצע** . ששונאין את ממונם בדין, כההיא דאמרינן (ב''ב נח:) כל דיינא דמפקין מיניה ממונא בדינא לאו דיינא הוא. לשון רש''י. ירצה לפרש שכל ממון שידעו בו שאדם יכול להוציאו מידם בדין ישנאו אותו ויחזירוהו מעצמם, ואפילו הוא שלהם באמת, כגון שקנה עבד שלא בעדים, וכיוצא בו. אבל הלשון במכילתא אינו כן, אלא כך שנויה שם שונאי בצע, שהן שונאין לקבל ממון בדין, דברי רבי יהושע. רבי אלעזר המודעי אומר, **שונאי בצע** , אלו שהן שונאין ממון עצמן, אם ממון עצמן שונאין קל וחומר ממון חבריהם. פירש רבי יהושע **שונאי בצע** , שונאי שוחד, כמו כולו בוצע בצע (ירמיה ו יג), איש לבצעו מקצהו (ישעיה נו יא). רבי אלעזר המודעי דרש כי הם השונאים הממון הרב, ואין להם חפץ ברבוי כסף וזהב, כענין אם אשמח כי רב חילי וכי כביר מצאה ידי (איוב לא כה). כי הממון יקרא בצע, מה בצע כי נהרוג את אחינו (בראשית לז כו), ואם בצע כי תתם דרכיך (איוב כב ג), והחרמתי לה' בצעם וחילם לאדון כל הארץ (מיכה ד יג):
@20 **ושוב** ראיתי בילמדנו **שונאי בצע** , ששונאין ממון עצמן ואין צריך לומר ממון אחרים, יהיו אומרים אפילו שורף גדישי אפילו קוצץ נטיעותי כהוגן אני דנו. וזה ענין ששונאין ממון עצמן שאמר רבי אלעזר המודעי, שלא יחמלו על ממונם בענין הדין אם יבא להם הפסד ממנו. ומשה הזהירם עוד בזה **לא תגורו מפני איש** (דברים א יז). והבצע ממון כמו שפירשתי:
@20 **ואונקלוס** אומר דסנן לקבלא ממון. ואין הממון אצלו שחד, רק שלא יקבלו ממון מבני אדם במתנה או בהלואה לעולם, שלא ישאו להם פנים בעת המשפט. וכענין שאמרו (כתובות קה:) האי דיינא דשאיל שאלתא אסור למידן דינא. ועל דרך הפשט **אנשי אמת שונאי בצע** , שהם אוהבים האמת ושונאים העושק, וכי יראו עושק וחמס אין דעתם סובלת אותו, אבל כל חפצם להציל גזול מיד עושק:
@22 וטעם **ושפטו את העם בכל עת** . כי בהיות להם שופטים רבים ילך העשוק אל השופט בכל עת שירצה וימצאנו מזומן, כי אליך לא יוכל להתקרב בכל עת מפני ההמון הגדול אשר לפניך והטרדה הגדולה אשר לך, ורבים מהם יסבלו החמס הנעשה להם מפני שלא יזדמן להם להגידו לך ולא ירצו לעזוב מלאכתם ועסקיהם עד בא העת הפנאי שיוכלו לגשת אליך:
@22 **וזה** טעם **איש על מקומו יבא בשלום** , כי עתה מפני שלא יוכלו לגשת למשפט בכל עת לא ינוחו בשלום, כי זה פתח לגוזלים לעשות חמס ולעושקים לעשות מריבה. וטעם על מקומו, אל כל המקום אשר יבאו שמה בהיותם במחנה במדבר. ודקדקו רבותינו (סנהדרין לד:) מלשון **ושפטו את העם בכל עת** , שדיני ממונות גומרין אפילו בלילה, כי לא אמר כל היום:
@28 (א~ב) **בחדש השלישי** . היה ראוי שיאמר הכתוב ויסעו מרפידים ויחנו במדבר סיני בחדש השלישי לצאתם מארץ מצרים, כמו שנאמר למעלה (טז א) במדבר סין, אבל בעבור היות ביאתם במדבר סיני שמחה להם ויום טוב, ומעת צאתם ממצרים נכספים אליו, כי ידעו ששם יקבלו את התורה, כי משה הגיד להם מה שנאמר לו **תעבדון את האלהים על ההר הזה** (לעיל ג יב), וגם לפרעה אמר **נלכה נא דרך שלשת ימים במדבר ונזבחה לה' אלהינו** (שם ה ג), והוא המהלך ממצרים ועד הר סיני, בעבור זה התחיל הפרשה כי **בחדש השלישי ביום הזה** שהתחיל החדש באו לשם. ואחרי כן חזר לומר כשאר המסעות **ויסעו מרפידים** :
@28 **והיה** ראוי ג''כ שיאמר ויסעו מרפידים ויחנו במדבר סיני, אבל כתב **ויבאו מדבר סיני** , לומר כי מיד שבאו אל מדבר סיני חנו במדבר בראותם ההר מנגד, ולא המתינו עד שיכנסו בו אל מקום טוב לחנות שם, אבל חנו במדבר או בחורב שהוא מקום חורב שממה לפני ההר. וזה טעם **ויחנו במדבר ויחן שם ישראל נגד ההר** :
@28 **ויתכן** שהבדילו מתוכם כל האספסוף אשר בקרבם, וחנו בני ישראל לבדם לפני ההר, וערב רב אחריהם, כי לישראל יתן התורה, כמו שאמר (בפסוק הבא) כה תאמר לבית יעקב ותגיד לבני ישראל. וזה טעם ויחן שם ישראל, או הוא להזכירם דרך כבוד בקבלם התורה:
@28 **ורש''י** כתב ויסעו מרפידים, מה הוצרך לחזור ולפרש מהיכן נסעו, והלא כבר נאמר (לעיל יז א) כי ברפידים היו חונים, בידוע שמשם נסעו, אלא מקיש נסיעתם מרפידים לחנייתם במדבר סיני מה חנייתן בתשובה אף נסיעתן בתשובה, לשון רש''י. ולא הבינותי זה, שכך נאמר בכל המסעות ויחנו באלים, ויסעו מאלים ויבאו אל מדבר סין (לעיל טז א), ויסעו ממדבר סין ויחנו ברפידים (שם יז א), וכן כל פרשת מסעי. וירצה הכתוב לפרש שלא היו חניות אחרות ביניהן:
@28 **ולשון** מכילתא (כאן) **ויסעו מרפידים ויבאו מדבר סיני** , והלא כבר נאמר בפרשת מסעות (במדבר לג טו) ויסעו מרפידים ויחנו במדבר סיני, ומה תלמוד לומר **ויבאו מדבר סיני** , מקיש נסיעתם מרפידים וכו'. והענין לומר מפני שכל המסעות שספר בהן כאן מאילים (לעיל טז א) ורפידים (שם יז א) נשנו בפרשת אלה מסעי בשביל דברים שנתחדשו בהן שם בכתוב, אבל המסע הזה סיפר אותו הכתוב כאן וכאן בשוה, והוצרך לדרוש שהיה לצורך ההיקש:
@30 **ומשה עלה אל האלהים** . מיום בואם אל הר סיני כסה הענן את ההר ושם כבוד ה', וזהו שכתוב (להלן כד טז) וישכן כבוד ה' על הר סיני ויכסהו הענן ששת ימים, קודם מתן תורה (יומא ד.), ולפיכך אמר **ומשה עלה אל האלהים** , כי עלה אל קצה ההר להזדמן לפניו, ולא בא אל הערפל אשר שם האלהים. ויקרא אליו השם מראש ההר **כה תאמר לבית יעקב ורבי** אברהם אמר כי ויקרא אליו מוקדם, שקרא לו ועלה אליו. ולא נראה לי, כי הקריאה היא **כה תאמר לבית יעקב** . והוא יפרש ויקרא אליו לאמר לו כה תאמר לבית יעקב. ואיננו נכון. וטעם **עלה אל האלהים** , **ויקרא אליו ה'** , כי עלה אל כבוד השם ששכן בהר לאמר לישראל עשרת הדברות, ובשמו הגדול ידבר עם משה, כטעם אם יהיה נביאכם וגו' (במדבר יב ו~ח):
@31 **ואביא אתכם אלי** . אל מקום כבודי, ההר הזה אשר שכינתי שם עמכם. ואונקלוס שתרגם וקריבת יתכון לפולחני, דרך כבוד של מעלה תפס לעצמו:
@32 וטעם **ושמרתם את בריתי** . הברית אשר כרתי את אבותיכם להיות להם לאלהים ולזרעם אחריהם (בראשית יז ז). ור''א אמר הברית שיכרות משה עם ישראל אחר מתן תורה, כמו שאמר (להלן כד ח) הנה דם הברית אשר כרת ה' עמכם על כל הדברים האלה:
@32 **ועל** דרך האמת, שתשמרו את בריתי לדבקה בי (להלן כג כב), כי אם שמוע תשמע בקולי ועשית כל אשר אדבר:
@32 **והייתם לי סגולה מכל העמים** . שתהיו בידי סגולה, כדבר נחמד לא ימסרנו המלך ביד אחר, כמו וסגולת מלכים והמדינות (קהלת ב ח):
@32 ואמר **כי לי כל הארץ** . כטעם אשר חלק ה' אותם לכל העמים, ואתכם לקח ה' (דברים ד יט כ). וכך אמר ואבדיל אתכם מן העמים להיות לי (ויקרא כ כז):
@32 **או** יהיה ''סגולה'' דבקות, כי לי הארץ הנקראת כל, כמו שפירשתי בפסוק וה' ברך את אברהם בכל (בראשית כד א). והמשכיל יבין:
@32 **וכן** ואתם תהיו לי (פסוק ו), שתהיו אתם לי ביחוד, ולא כשאר העמים. וכך אמרו במכילתא (שם) **ואתם תהיו לי** , כביכול איני מעמיד ואיני משליט עליכם אלא אני, וכן הוא אומר הנה לא ינום ולא יישן שומר ישראל (תהלים קכא ד):
@33 **ממלכת כהנים** . ותהיו ממלכת משרתי:
@33 **וגוי קדוש** . לדבקה באל הקדוש, כמו שאמר קדושים תהיו כי קדוש אני ה' (ויקרא יט ב). והנה הבטיחם בעולם הזה ובעולם הבא:
@34 **וישם לפניהם את כל הדברים האלה** . טעמו שאמר להם הנה נתתי לפניכם הדברים, בחרו לכם היום אם תעשון כן, ולכן ענו אותו **כל אשר דבר ה' נעשה** (פסוק ח), כטעם ראה נתתי לפניכם היום את החיים ואת הטוב ואת המות ואת הרע (דברים ל טו). וכן ואלה המשפטים אשר תשים לפניהם (להלן כא א), שיאמרו שאם יבחרו ויקבלו עליהם לעשותם. ועל כן אמר שם (כד ג) ויבא משה ויספר לעם את כל דברי ה' ואת כל המשפטים, ויען כל העם קול אחד ויאמרו כל הדברים אשר דבר ה' נעשה. וכן וזאת התורה אשר שם משה לפני בני ישראל (דברים ד מד), שאמר לדור הבא בארץ אם יקבלו עליהם את התורה, כי בא לכרות עמהם ברית בערבות מואב כאשר כרת עם אבותיהם בחורב:
@34 **והגאון** רב סעדיה אמר כי וישם לפניהם כמו שימה בפיהם (דברים לא יט). ואיננו אלא כמו שפירשתי. וכן טעם ויענו כל העם יחדיו, כי משה קרא לזקני העם שהם חכמיהם ושופטיהם, כי להם הבחירה, ושם לפניהם כל הדברים האלה במעמד כל העדה, כי על כלם צוה כה תאמר לבית יעקב ותגיד לבני ישראל (פסוק ג), והם לא המתינו לעצה ובחירה, ויענו כל העם יחדו ויאמרו למקטון ועד גדול כל אשר דבר ה' נעשה, וכן אמר עוד (להלן כד ג) ויען כל העם קול אחד ויאמרו:
@35 **וישב משה את דברי העם אל ה'** . ששב לפניו אל ההר עם מענה העם. והנה הכל גלוי לפניו ולא שאלו מה ענה לך העם הזה, וכענין שכתוב וישמע ה' את קול דבריכם בדברכם אלי. ובבאו לפניו אמר ה' יתברך **הנה אנכי בא אליך בעב הענן בעבור ישמע העם בדברי עמך וגם בך יאמינו לעולם** , ואז הגיד לפניו ואמר רבונו של עולם בניך מאמינים הם ומקבלין עליהם כל אשר תדבר, וכן וישיבו אותם דבר ויראום את פרי הארץ (במדבר יג כו), שובם אליהם עם הדברים שראו, כי אח''כ אמר ויספרו לו ויאמרו. ואין צורך לדברי ר''א בזה:
@36 **בעב הענן** . הוא הערפל אשר שם האלהים (להלן כ כא), והכל רואין ומכירין כן, כמו שאמר ומראה כבוד ה' כאש אוכלת בראש ההר לעיני בני ישראל (להלן כד יז):
@36 **בעבור ישמע העם בדברי עמך** . אמר ר''א כי היו בישראל אנשים שהיתה להם הנבואה בספק, ואע''פ שכתוב (לעיל יד לא) ויאמינו בה' ובמשה עבדו, שם אמר וירא ישראל, ולא כל ישראל, וזהו שאמרו אליו היום הזה ראינו כי ידבר אלהים את האדם וחי (דברים ה כא), כי לא היו מאמינים כן מתחלה. וזה טעם **בעבור ישמע העם בדברי עמך** , עשרת הדברים, וגם בך יאמינו, שאתה נביאי, כי מעתה יתאמת אצלם ענין הנבואה. ואיננו נכון, כי זרע אברהם לא יסתפקו בנבואה, כי האמינו בה מאבותם. וכבר אמר עוד ויאמן העם וישמעו (לעיל ד לא), ויאמינו בה' ובמשה עבדו (לעיל יד לא), ואם לא אמר שם כל העם וכל ישראל, אף כאן לא נאמר בעבור ישמע כל העם:
@36 **והנכון** בעיני שאמר, **אני בא אליך בעב הענן** , שתגש אתה אל הערפל בעבור ישמע העם דברי, ויהיו הם עצמם נביאים בדברי, לא שיאמינו מפי אחרים, כמו שנאמר באמור ה' אלי הקהל לי את העם ואשמיעם את דברי למען ילמדון ליראה אותי כל הימים (דברים ד י), וגם בך יאמינו לנצח בכל הדורות, ואם יקום בקרבם נביא או חולם חלום כנגד דברך יכחישוהו מיד, שכבר ראו בעיניהם ושמעו באזניהם שהגעת למעלה העליונה בנבואה, יתברר להם ממך מה שכתוב (במדבר יב ו~ח) אם יהיה נביאכם ה' במראה אליו אתודע בחלום אדבר בו, לא כן עבדי משה בכל ביתי נאמן הוא פה אל פה אדבר בו, ולכך אמר **בעבור ישמע העם בדברי עמך** , כי ישמע דברי מתוך האש וידעו שאני ה' מדבר עמך ויאמינו בדברי **וגם בך לעולם וכן** מה שאמרו היום הזה ראינו כי ידבר אלהים את האדם וחי (דברים ה כא), לומר הנה נתקיים הדבר אצלינו בראיית עינינו כאשר היה חפץ אלהים, ומעתה **קרב אתה** שידענו בך שהגעת למעלה הגדולה **ושמע כל אשר אמר ה' אלהינו ושמענו מפיך ועשינו** , שכבר נאמנה נבואתך כי היא העליונה על כל הנביאים:
@36 **ובמכילתא** (כאן) ראיתי **בעבור ישמע העם בדברי עמך** , מלמד שאמר הקב''ה למשה, הרי אני קורא לך מראש ההר ואתה עולה, שנאמר (להלן פסוק כ) ויקרא ה' למשה, **וגם בך יאמינו לעולם** , גם בך גם בנביאים העתידים לעמוד אחריך. מטין דבריהם לדעת ר''א:
@37 **וקדשתם היום ומחר** . פירש רש''י וזמנתם. וכן דעת אונקלוס. וכמהו אני צויתי למקודשי (ישעיה יג ג), וכן התקדשו למחר (במדבר יא יח). ור''א אמר שירחצו במים. ומה טעם **היום ומחר** , ואין צריך לרחוץ אלא פעם אחת. והנכון שיהיו קדושים, שלא יגשו אל אשה ואל כל טומאה, כי הנשמר מן הטומאה יקרא מקודש, כמו שאמר בכהנים לנפש לא יטמא (ויקרא כא א), קדושים יהיו לאלהיהם (שם ו), וכתיב כי הכהנים לא התקדשו (דהי''ב ל ג), ר''ל לא הטהרו, וכן כי אם אשה עצורה לנו ויהיו כלי הנערים קדש (ש''א כא ו). ובידוע כי ירחצו במים, והוא נלמד מכבוס הבגדים. וכך אמרו במכילתא (כאן) אין כבוס בגדים בתורה שאין טעון טבילה:
@38 **ירד ה' לעיני כל העם** . שכלם יראו ברדתו שם, כי יראו מראה כבוד ה' כאש אוכלת בראש ההר. לא שיראו את השם, דכתיב (להלן לג כ) כי לא יראני האדם וחי:
@40 **במשוך היובל המה יעלו בהר** . הוא שופר של איל, ושופר אילו של יצחק היה (פדר''א לה). לשון רש''י. ולא הבינותי זה, כי אילו של יצחק עולה הקריב אותו, והקרנים והטלפים הכל נשרף בעולות (זבחים פה:). אולי גבל הקב''ה עפר קרנו והחזירו למה שהיה:
@40 **אבל** לפי דעתי האגדה הזו יש לה סוד, ואמרו שזה הקול הוא פחד יצחק, ולכך אמר (פסוק טז) ויחרד כל העם אשר במחנה, ולא השיגו דבור בגבורה הזאת זולתי קול (דברים ד יב):
@41 **וירד משה מן ההר אל העם ויקדש את העם** . לימד כאן שגם הדבור הזה שאמר בו **ויאמר ה' אל משה לך אל העם** , היה בהר, שהיה משה עולה שם בכל פעם לדבר אתו. ובמכילתא (כאן) דרשו בו מלמד שלא היה משה פונה לעסקיו ולא היה הולך לביתו כלל אלא **מן ההר אל העם** :
@46 **משה ידבר והאלהים יעננו בקול** . אמרו במכילתא (כאן) שזה על שעת מתן תורה, שהיה משה משמיע הדברות לישראל, כמו שכתב רש''י. ועל דרך הפשט לא ידבר בזה עדיין, אבל ירד השם הנכבד אל ההר ביום השלישי, והוציא משה את העם מן המחנה לקראת הכבוד הנראה להם, **ויתיצבו הם בתחתית ההר** , ומשה עלה למעלה קרוב לראש ההר ששם הכבוד מחיצה לעצמו ומדבר עם ישראל להורותם מה יעשו, וישראל שומעים קול האלהים שעונה אותו ויצונו והם לא יבינו מה יאמר לו, ויצוה אותו בצואות האמורות אח''כ בפרשה **רד העד בעם וגו'** , **לך רד ועלית אתה ואהרן עמך** וגו', והיה זה קודם מתן תורה וגם בשעת הדברות, כי משה לא עלה אל ראש ההר **אל הערפל אשר שם האלהים** רק לאחר מתן תורה. וכן אמר (דברים ה ה) אנכי עומד בין ה' וביניכם בעת ההיא להגיד לכם את דבר ה' כי יראתם מפני האש ולא עליתם בהר לאמר, כאשר עליתי אני. ויש מפרשים כי ישראל יראים מאד מקול השופר שהולך וחזק מאד (פסוק יט), ומשה היה אומר תחלה כוונו דעתכם כי עתה תשמעו קול בענין כך, ומיד **האלהים יעננו** אותו **בקול** :
@47 **וירד ה' על הר סיני** . אם תשכיל בפרשה תבין כי שמו הגדול ירד על הר סיני ושכן עליו באש, והוא מדבר עם משה, והדבור עם משה בכל הפרשה בשם המיוחד, והעליה (לעיל פסוק ג) והיציאה (שם פסוק יז) לקראת מקום הכבוד, כמו שפירשתי (לעיל פסוק ג), והזהיר **פן יהרסו אל ה' לראות** , כי גם אצילי בני ישראל לא חזו אותו, וכל ישראל שמעו קול השם מתוך האש, והוא שנאמר (להלן כ א) וידבר אלהים את כל הדברים האלה, כמו שאמרו רבותינו (מכילתא ד) אין אלהים אלא דיין, ואמרו (מכות כד.) מפי הגבורה שמענום, ובמשנה תורה (דברים ה יט) כתוב את הדברים האלה דבר ה' אל כל קהלכם, בעבור שפי' מתוך האש. וזה טעם פנים בפנים (שם ה ד), ולכך נאמר אנכי ה' אלהיך. ואל יקשה עליך מה שאמרו הם למשה כי מי כל בשר אשר שמע קול אלהים חיים מדבר מתוך האש, כי לא אמרו אשר שמע אלהים מדבר מתוך האש, אבל אמר קול אלהים, שאמרו מה שהשיגו, ולכך אמרו קרב אתה ושמע את כל אשר יאמר ה' אלהינו (דברים ה כד), וכן אמר להם משה השמע עם קול אלהים מדבר מתוך האש (שם ד לג), כי מדבר תואר לקול, כענין וישמע את הקול מדבר אליו (במדבר ז פט):
@47 **ומזה** תבין מה שאמרו רבותינו תמיד במדרשי הגדות (עי' שמו''ר כח ו) כי בשבעה קולות נתנה התורה, והם שהזכיר דוד במזמור הבו לה' בני אלים (תהלים כט), והוא המנין הנרמז בפרשה הזאת, כי **ויהי קלת וברקים** חסר וימנה אחד, וכן **וכל העם רואים את הקולת** יחסר ממנו הרבים, והנה הם ששה, וכבר נאמר בפירוש. **וידבר אלהים** , וכן במשנה תורה (דברים ד וה) הזכיר שבעה קולות במתן תורה, ובמסכת ברכות (ו:) אמרו בגמרא שנתנה בחמשה קולות שהם יחשבו הקולות הנסתרים והשנים מפורשים להם בכתוב, והכוונה כי למשה רבינו נתנה בשבעה הקולות, והוא השומע ומתבונן בהם, אבל לישראל בקול אחד ישמעו, כמו שאמר קול גדול ולא יסף (דברים ה יט), ונאמר קול דברים אתם שומעים ותמונה אינכם רואים זולתי קול (שם ד יב), ואף כאן רמז **וכל העם רואים את הקולת** בחסרון וי''ו אחד, כי כל הקולות יראו אחד, והוא מה שנאמר (תהלים סב יב) אחת דבר אלהים שתים זו שמענו, על דרך האמת. והנה הפרשיות מבוארות, לא יתחלף להם דבר בדבר:
@49 **וגם הכהנים הנגשים אל ה'** . שהם מגישים לשם הנכבד קרבנות ונגשים בהם אליו:
@54 **אנכי ה' אלהיך** . הדבור הזה מצות עשה, אמר אנכי ה', יורה ויצוה אותם שידעו ויאמינו כי יש ה', והוא אלהים להם, כלומר הווה, קדמון, מאתו היה הכל בחפץ ויכולת, והוא אלהים להם, שחייבים לעבוד אותו. ואמר אשר הוצאתיך מארץ מצרים, כי הוצאתם משם תורה על המציאות ועל החפץ, כי בידיעה ובהשגחה ממנו יצאנו משם, וגם תורה על החדוש, כי עם קדמות העולם לא ישתנה דבר מטבעו, ותורה על היכולת, והיכולת תורה על הייחוד, כמו שאמר (לעיל ט יד) בעבור תדע כי אין כמוני בכל הארץ. וזה טעם אשר הוצאתיך, כי הם היודעים ועדים בכל אלה:
@54 וטעם **מבית עבדים** . שהיו עומדים במצרים בבית עבדים, שבויים לפרעה, ואמר להם זה שהם חייבין שיהיה השם הגדול והנכבד והנורא הזה להם לאלהים, שיעבדוהו, כי הוא פדה אותם מעבדות מצרים, כטעם עבדי הם אשר הוצאתי אותם מארץ מצרים (ויקרא כה נה). וכבר רמזתי עוד למעלה (יט כ) טעם שני השמות הקדושים על דרך האמת:
@54 **וזו** המצוה תקרא בדברי רבותינו (ברכות יג:) קבלת מלכות שמים, כי המלות האלה אשר הזכרתי הם במלך כנגד העם. וכך אמרו במכילתא (בפסוק הבא) **לא יהיה לך אלהים אחרים על פני** למה נאמר, לפי שהוא אומר אנכי ה' אלהיך, משל למלך שנכנס למדינה, אמרו לו עבדיו גזור עלינו גזירות, אמר להם לאו, כשתקבלו מלכותי אגזור עליכם גזירות, שאם מלכותי אינכם מקבלים גזירותי האיך אתם מקיימין. כך אמר המקום לישראל אנכי ה' אלהיך לא יהיה לך, אני הוא שקבלתם מלכותי עליכם במצרים, אמרו לו הן, כשקבלתם מלכותי קבלו גזרותי, כלומר אחר שאתם מקבלים עליכם ומודים שאני ה' ואני אלהיכם מארץ מצרים קבלו כל מצותי:
@54 **ונאמרו** כל הדברות כלן בלשון יחיד, ה' אלהיך אשר הוצאתיך, ולא כאשר התחיל להם **אתם ראיתם** וגו', **אם שמע תשמעו** (לעיל יט ד ה), להזהיר כי כל יחיד מהם יענש על המצות, כי עם כל אחד ידבר, ולכל אחד יצוה שלא יחשבו כי אחר הרוב ילך והיחיד ינצל עמהם. ויבאר להם משה זאת הכוונה בסוף התורה בפרשת אתם נצבים (דברים כט יז):
@55 **לא יהיה לך אלהים אחרים על פני** . כתב רש''י **לא יהיה לך** למה נאמר, לפי שנאמר **לא תעשה לך** , אין לי אלא שלא יעשה, העשוי כבר מנין שלא יקיים, ת''ל. **לא יהיה לך** . וזו באמת ברייתא היא שנוייה במכילתא (כאן). וא''כ תהיה זו מצות לא תעשה בלבד אזהרה למקיים ע''ג ברשותו ואין בה מיתת ב''ד, ולמה הקדים הקיום שהוא בלאו להשתחואה ועבודה שהם בכרת ומיתת ב''ד. ולפי דעתי שאין הלכה כדברי זאת הברייתא, וכדברי יחיד היא שנויה, שכך שנינו בסיפרא (ריש קדושים) **ואלהי מסכה לא תעשו לכם** (ויקרא יט ד), יכול יעשו לכם אחרים, ת''ל לא לכם. אין לי אלא לכם, יכול הן יעשו לאחרים, ת''ל לא תעשו לא לכם ולא לאחרים. מכאן אמרו העושה ע''ג לעצמו עובר משום שתי אזהרות, משום לא תעשו ומשום לא לכם. רבי יוסי אומר משום שלש, משום לא תעשו ומשום לא לכם ומשום לא יהיה. הרי שר' יוסי יחיד במקום רבים הוא האומר כי לא יהיה לך אזהרה למקיים ע''ג, ולדברי תנא קמא אינו כן:
@55 **והנכון** גם לפי הפשט שהוא מלשון והיה ה' לי לאלהים (בראשית כח כא), להיות לכם לאלהים (ויקרא יא מה). יאמר, שלא יהיה לנו בלתי השם אלהים אחרים מכל מלאכי מעלה ומכל צבא השמים הנקראים אלהים, כענין שנאמר (להלן כב יט) זובח לאלהים יחרם בלתי לה' לבדו, והיא מניעה שלא יאמין באחד מהם ולא יקבלהו עליו באלוה ולא יאמר לו אלי אתה. וכן דעת אונקלוס שאמר אלה אחרן בר מיני:
@55 **ודע** כי בכל המקום שאמר הכתוב ''אלהים אחרים'' הכוונה בו אחרים זולתי השם הנכבד, ויתפוס זה הלשון בקבלת האלהות או בעבודה לו, כי יאמר לא תקבלו עליכם אלוה בלתי ה' לבדו, אבל כשידבר בעשייה לא יאמר בכתוב אחרים חלילה, אבל יאמר ואלהי מסכה לא תעשו לכם (ויקרא יט ד), אלהי מסכה לא תעשה לך (להלן לד יז), ויקראם כן בעבור שיעשה בכוונה להיות אלהיו. אבל בהם אמר הכתוב (ישעיה לז יט) כי לא אלהים המה כי אם מעשה ידי אדם ואבן ויאבדום:
@55 **והנה** הזהיר בדבור השני תחלה שלא נקבל לנו אדון מכל האלהים זולתי ה', ואחר כך אמר שלא נעשה פסל וכל תמונה להשתחוות להם ולא לעבדם בשום עבודה בעולם. ולכך לא אמר ולא תשתחוה להם, כי הוא נסמך אל העשייה שמנע אותנו מהשתחוות להם. והנה כלם אזהרות מעבודה זרה, וכלן חייבי מיתה, ואין בפסוק הזה אזהרה לעושה עבודה זרה שלא עבדם, אבל למטה יזהיר מזה אלהי כסף ואלהי זהב לא תעשו לכם (להלן פסוק כג), וכן אלהי מסכה לא תעשה לך (להלן לד יז), לא תעשו לכם אלילים (ויקרא כו א):
@55 וטעם **על פני** . כמו אם לא על פניך יברכך (איוב א יא), ועתה הואילו פנו בי ועל פניכם אם אכזב (שם ו כח). יזהיר לא תעשה לך אלהים אחרים, כי על פני הם, שאני מסתכל ומביט בכל עת ובכל מקום בעושים כן. הדבר העשוי בפניו של אדם והוא עומד עליו יקרא ''על פניו'', וכן ותעבור המנחה על פניו (בראשית לב כב), וכן וימת נדב ואביהוא ויכהן אלעזר ואיתמר על פני אהרן אביהם, שהיה אהרן אביהם רואה ועומד שם, ובדברי הימים (א כד ב) וימת נדב ואביהוא לפני אביהם ובנים לא היו להם. והנה אמר **לא תעשה לך אלהים אחרים** שאני נמצא עמך תמיד ורואה אותך בסתר ובגלוי:
@55 **ועל** דרך האמת תבין סוד הפנים ממה שכתבנו (לעיל ג ב), כי הכתוב הזהיר במעמד הזה פנים בפנים דבר ה' עמכם (דברים ה ד), ותדע סוד מלת אחרים, ויבא כל הכתוב כפשוטו ומשמעו. וכן רמז אונקלוס, והוא שנאמר (פסוק כג) לא תעשון אתי וגו':
@57 **כי אנכי ה' אלהיך** . לבדי, ואין ראוי שתשתף עמי אחרים. ואנכי אל, תקיף, שיש לאל ידי, וקנא, שאקנא בנותן כבודי לאחר ותהלתי לפסילים. ולא נמצא בכתוב בשום מקום שיבא לשון קנאה בשם הנכבד כי אם בענין עבודה זרה בלבד. ואמר הרב במורה הנבוכים (א לב) שלא תמצא בכל התורה ובכל ספרי הנביאים לשון חרון אף ולא לשון כעס ולא לשון קנאה אלא בענין ע''ז בלבד. והנה בקדושי עליון, ויחר אף ה' במשה (לעיל ד יד), ויחר אף ה' בם וילך (במדבר יב ט), וכתוב (איוב מב ז) חרה אפי בך ובשני רעיך כי לא דברתם אלי נכונה כעבדי איוב. אבל בלשון קנאה אמת הוא. וכך אמרו במכילתא (כאן) בקנאה אני נפרע מע''ז אבל אני חנון ורחום בדברים אחרים:
@57 **ולפי** דעתי שיזכיר קנאה בע''ז בישראל בלבד, וטעם הקנאה כי ישראל סגולת השם הנכבד אשר הבדילם לו, כאשר פירשתי למעלה (יט ה). והנה אם העם שלו משרתיו פונים אל אלהים אחרים יקנא בהם השם כאשר האיש מקנא באשתו בלכתה לאחרים, ובעבדו בעשות לו אדון אחר, ולא יאמר הכתוב כן בשאר העמים אשר חלק להם צבאות שמים:
@57 **ובכאן** אני מזכיר מה שיורו הכתובים בענין ע''ז, כי היו שלשה מינין. הראשונים החלו לעבוד את המלאכים שהם השכלים הנבדלים בעבור שידעו למקצתם שררה על האומות, כענין שכתוב (דניאל י כ) שר מלכות יון ושר מלכות פרס, וחשבו שיש להם יכולת בם להיטיב או להרע, וכל אחד עובד לשר שלו כי היו הראשונים יודעים אותם, ואלה הם הנקראים בתורה ובכתובים כלם אלהים אחרים, אלהי העמים, כי המלאכים נקראים אלהים, כמו שנאמר הוא אלהי האלהים (דברים י יז), השתחוו לו כל אלהים (תהלים צז ז), כי גדול ה' מכל האלהים (לעיל יח יא). ואע''פ שהיו העובדים מודים שהכח הגדול והיכולת הגמורה לאל עליון, וכך אמרו רבותינו (מנחות קי:) דקרו ליה אלה דאלהיא, ובזה אמר הכתוב זובח לאלהים יחרם הזכירם בשם הידיעה:
@57 **והמין** השני בע''ז, שחזרו לעבוד לצבא השמים הנראה, מהם עובדי השמש או הירח, ומהם למזל מן המזלות, כי כל אחת מן האומות ידעה כח המזל בה כפי משטרו על הארץ שלהם, וחשבו כי בעבודתם יגבר המזל ויועיל להם, כענין שכתוב (ירמיה ח ב) ושטחום לשמש ולירח ולכל צבא השמים אשר אהבום ואשר עבדום ואשר הלכו אחריהם ואשר דרשום ואשר השתחוו להם, וכמו שנאמר בתורה באיסור של ע''ז (דברים ד יט) ופן תשא עיניך השמימה וראית את השמש ואת הירח ואת הכוכבים כל צבא השמים ונדחת והשתחוית להם ועבדתם אשר חלק ה' אלהיך אותם לכל העמים תחת כל השמים. יאמר, כי בעבור שחלק השם אותם לכל העמים ונתן לכל עם כוכב ומזל לא תהיה נדח אחריהם לעבדם, ואלה האנשים הם שהחלו לעשות הצורות הרבות בפסילים והאשרים והחמנים, כי היו עושים צורות מזלם בשעות אשר להם הכח כפי מעלתם, והיו נותנים בעם, כפי מחשבתם, כח והצלחה:
@57 **וקרוב** בעיני שהוחל זה בדור הפלגה כאשר הפיצם השם אל הארצות, ומשלו בהם הכוכבים והמזלות למחלקותיהם, כי הבונים היו רוצים לעשות להם שם ולא יתחלקו, כאשר רמזתי במקומו (בראשית יא ב):
@57 **והיו** לכל אלה הכתות נביאי שקר מגידים להם מן העתידות ומודיעים קצת הבאות עליהם בחכמת הקסם והניחוש, כי יש גם למזלות שרים שוכנים באויר כמלאכים בשמים יודעים בעתידות. וממין העבודה הזאת היו מהם עובדים לאנשים, כי בראותם לאחד מבני האדם ממשלה גדולה ומזלו עולה מאד כנבוכדנצר, היו אנשי ארצו חושבים כי בקבלם עליהם עבודתו וכוונתם אליו יעלה מזלם עם מזלו, והוא ג''כ יחשוב כי בהדבק מחשבתם בו תוסיף לו הצלחה בכח נפשותיהם המכוונות אליו. וזה היה דעת פרעה כדברי רבותינו (שמו''ר ט ז), ודעת סנחריב שאמר הכתוב במחשבתו אעלה על במתי עב אדמה לעליון (ישעיה יד יד), וחירם וחביריו שעשו עצמם אלוהות, כי היו רשעים לא שוטים גמורים:
@57 **והמין** השלישי בע''ז, אחר כך חזרו לעבוד את השדים שהם רוחות, כאשר אפרש בע''ה (ויקרא יז ז), כי גם מהם יש ממונים על האומות שיהיו הם בעלי הארץ ההיא להזיק לצריהם ולנכשלים שבהם, כידוע מענינם בחכמת נגרמונסיא, גם בדברי רבותינו. ובזה אמר הכתוב (דברים לב יז) יזבחו לשדים לא אלוה אלהים לא ידעום חדשים מקרוב באו לא שערום אבותיכם, לעג להם הכתוב שהם זובחים גם לשדים שאינם אלוה כלל, כלומר שאינם כמלאכים הנקראים אלוה, אבל הם אלהים שלא ידעום, כלומר שלא מצאו בהם שום אלהות וכח שולטנות, והם חדשים להם שלמדו לעשות כן מחדש מן המצרים המכשפים, וגם אבותיהם הרשעים כתרח ונמרוד לא שערום כלל. ומזה מזהיר ולא יזבחו עוד את זבחיהם לשעירים אשר הם זונים אחריהם (ויקרא יז ז):
@57 **והנה** התורה אסרה בדבור הזה השני כל עבודה בלתי לה' לבדו, ולכך הזהיר בתחלה **לא יהיה לך אלהים אחרים על פני** , שהם המין הראשון, וזהו **על פני** , כאשר רמזתי סודו. והזהיר עוד על הפסל וגם על התמונה שהיא תרמוז גם לדבר הרוחני המדומה, כענין שכתוב (איוב ד טז) יעמוד ולא אכיר מראהו תמונה לנגד עיני. וכך אמרו (ר''ה כד:) **אשר בשמים** , לרבות חמה ולבנה כוכבים ומזלות. ממעל, לרבות מלאכי השרת. כי גם בהם יעשו צורות לשכלים הנבדלים אשר הם נפש למזלות, כאשר היה בענין מעשה העגל שאני עתיד. לפרש בע''ה (להלן לב א). ואמר **אשר במים מתחת לארץ** לרבות השדים, מתחת מים ושוכניהם (איוב כו ה), וכך אמרו (במכילתא כאן) להביא את הבוביא. ואמר בכלם לא תשתחוה להם ולא תעבדם בשום עבודה כלל, ואפילו לא יהא דעתו להוציא עצמו מרשותו של הקב''ה, והנה ריקן כל העבודות כלן לשם המיוחד ית' (סנהדרין ס:):
@57 **פוקד עון אבות על בנים** . אמר ר''א כי טעם פקידה כטעם זכירה, כמו וה' פקד את שרה (בראשית כא א), שהוא כמו ויזכרה ה' (ש''א א יט). והטעם, כי השם יאריך לרשע אולי ישוב ויוליד בן צדיק, אבל אם הלך הבן בדרכי אביו גם הדור השלישי גם הדור הרביעי יאבד זכרם. כי השם יזכור מה שעשו האבות, ולא יאריך עוד. וכזה אמרו כל המפרשים. וא''כ לא יפקוד עון אבות על בנים ועל שלשים, רק על רבעים, וראוי היה שיאמר פוקד עון אבות ובנים ושלשים על רבעים. ואולי יאמרו שהוא זוכר העון על הבנים לאמר אתה ואביך חטאתם, וכן יעשה עם השלשים ועם הרבעים, ואז ינקם מהם ולא יפקוד להם עוד כי יכריתם בעון כולם:
@57 **ואין** פירושם נכון, שיאמר הכתוב הזכירה בכלם בשוה, ולא יזכיר הנקמה שתהא ברבעים בסוף. ולשון פקידה עם מלת ''על'' לא תבא על זכירה, אבל היא הנקמה, וכן וביום פקדי ופקדתי עליהם חטאתם (להלן לב לד), וכן יפקוד ה' בחרבו הקשה והגדולה והחזקה על לויתן נחש בריח ועל לויתן נחש עקלתון והרג את התנין אשר בים (ישעיה כז א), וכן יפקוד ה' על צבא המרום במרום (שם כד כא), כלם הנקמה והעונש:
@57 **והנכון** בעיני שיאמר כי הוא פוקד העון אשר עשה האב על בניו ומכריתם בעון אביהם, כענין שנאמר (שם יד כא) הכינו לבניו מטבח בעון אבותם, וכן יפקוד אותו על שלשים כשלא יהיה עונם שלם בשני הדורות, כענין כי לא שלם עון האמורי עד הנה (בראשית טו טז). ופעמים יפקוד עון כלם על הרבעים שנתמלאה סאתם ויכריתם, אבל בדור חמישי לא יענש הבן בעון אביו הראשון. והוסיף במשנה התורה (דברים ה ט) ועל שלשים ועל רבעים לשונאי, כטעם או:
@57 **ואמר** ר''א כי בני הבנים נקראים בנים, על כן אחז דרך קצרה, כי ממלת שלשים ורבעים יתבונן זה. ואיננו כן, אבל שלשים, הדור השלישי בעון, ורבעים כן, כי הם ארבע חטאים. והכתוב שאמר בשלש עשרה מדות (להלן לד ז) פוקד עון אבות על בנים ועל בני בנים על שלשים ועל רבעים, יפרש על בני בנים השלשים והרבעים. ולפיכך חזר משה במרגלים ואמר על בנים על שלשים ועל רבעים (במדבר יד יח), ולא הזכיר בני בנים, והכל אחד:
@57 **ואמר** הכתוב לשונאי, כשיהיו הבנים שונאי השם, שאם הוליד בן צדיק לא ישא בעון האב, כמו שפי' יחזקאל (יחזקאל יח כ):
@57 **ומדברי** רבותינו (מכילתא כאן) נראה כפירוש הזה שפירשתי, שלמדו מכאן שמדה טובה מרובה על מדת פורענות, שמדת פורענות לארבעה דורות וכו', ואם היה כפירוש הראשון הזה שפירשתי, היתה מדה טובה מרובה אם יאריך גם דור עשירי. ויתכן שתהיה המדה החמורה הזאת בעבודת גלולים בלבד, כי בה יזהיר, אבל בשאר המצות איש בעונו ימות (ירמיה לא כט). והסוד הנסתר בפוקד עון אבות על בנים בתחלת ספר קהלת (א ד) תמצאנו, וכבר כתבתיו (בראשית לח ט):
@58 **לאהבי ולשומרי מצותי** . הנראה ממשמעות הכתוב שזו הבטחה בענין המצות האלו אשר הזכיר, יאמר כי הוא עושה בהן **חסד לאלפים לאהביו** , הם המוסרים נפשם עליו, כי המודים בשם הנכבד ובאלהותו לבדו ויכפרו בכל אלוה נכר ולא יעבדו אותם עם סכנת נפשם, יקראו אוהביו, כי זו היא האהבה שנתחייבנו בה בנפשותינו, כמו שאמר ואהבת את ה' אלהיך בכל לבבך ובכל נפשך (דברים ו ה), שתמסור נפשך וחייך באהבתו, שלא תחליפנו באל אחר, ולא תשתף עמו אל נכר. ולכך נאמר באברהם זרע אברהם אוהבי (ישעיה מא ח), שנתן נפשו שלא יעבוד ע''ז באור כשדים. ושאר הצדיקים יקראו שומרי מצותיו:
@58 **ורבים** פירשו (עי' רמב''ם בפירוש משנה סנהדרין ריש פרק י) כי אוהביו העובדים מאהבה שלא על מנת לקבל פרס, כמו שהזכירו חכמים (בספרי דברים יא יג):
@58 **ומצאתי** במכילתא (כאן) לאוהבי, זה אברהם וכיוצא בו. ולשומרי מצותי, אלו הנביאים והזקנים. רבי נתן אומר, לאוהבי ולשומרי מצותי, אלו שהם יושבים בארץ ישראל ונותנין נפשם על המצות. מה לך יוצא ליהרג, על שמלתי את בני. מה לך יוצא לישרף, על שקראתי בתורה. מה לך יוצא ליצלב, על שאכלתי את המצה. מה לך לוקה מאפרגל, על שנטלתי את הלולב. ואומר (זכריה יג ו) אשר הוכיתי בית מאהבי, המכות האלה גרמו לי ליאהב לאבי שבשמים. הרי פירש רבי נתן כי האהבה מסירת הנפש על המצוה. והכתוב ודאי על ע''ז כי בה נתחייבנו ביהרג ואל יעבור בכל הזמנים לעולם, אבל הרחיב הענין לכל המצות, לפי שבשעת השמד אנו נהרגין על כלן מן הכתוב האחר ולא תחללו את שם קדשי (ויקרא כב לב). ות''ק שאמר זה אברהם ואלו הנביאים, אינו נכון שיאמר שהיו הנביאים עושים על מנת לקבל פרס, אבל יש בזה סוד, אמר שאברהם מסר נפשו באהבה, כענין שכתוב חסד לאברהם, ושאר הנביאים בגבורה. והבן זה:
@59 **לא תשא את שם ה' אלהיך לשוא** . כבר נתפרש זה הכתוב בדברי רבותינו (שבועות כא.) שהוא אוסר להשבע בשם הנכבד לריק, כגון הנשבע על הידוע לאדם לשנותו או לקיימו, על עמוד של שיש שהוא של זהב או שהוא של שיש, והוא עומד לפניהם ומכירים בו. ועל דרך הפשט יאסור עוד שלא ישא על שפתיו השם הנכבד על חנם, כלשון לא תשא שמע שוא (להלן כג א), ובל אשא את שמותם על שפתי (תהלים טז ד), כי הדבור יקרא כן בעבור שישא בו קול. וכן משא דבר ה' (זכריה ט א), וכן ישא ביום ההוא לאמר לא אהיה חובש (ישעיה ג ז), שישא קולו לאמר כן:
@59 **ובאמת** שגם זה אסור, ונקרא בלשון חכמים מוציא שם שמים לבטלה (תמורה ג:). וכבר אמרו רבותינו (ספרא ויקרא ב, נדרים י:) מנין שלא יאמר אדם לה' עולה, לה' חטאת, אלא יאמר עולה לה', חטאת לה', ת''ל קרבן לה' (ויקרא א ב), והלא דברים קל וחומר, ומה אם מי שהוא עתיד להקדיש אמרה תורה לא יחול שמי אלא על הקרבן, קל וחומר וכו':
@59 **וסדר** זו המצוה אחר אזהרת ע''ז, כי כאשר ראוי ליראה את ה' הגדול והנורא שלא לתת כבודו לאחר, כן ראוי לתת כבוד לשמו, והנושא אותו לשוא מחללו, כענין שכתוב ולא תשבעו בשמי לשקר וחללת את שם אלהיך (ויקרא יט יב). וכמו שהחמיר בע''ז וכתב העונש כי הוא אל קנא פוקד עון אבות על בנים, כן כתב בזה העונש כי לא ינקה אותו. ואמר בלשון הזה, ולא אמר כי יפקוד עליו, בעבור שאינו אצל הנשבעים עבירה גמורה ויחשוב שראוי למחול לו, אמר כי לא ינקה כל הנוגע. ודבר ר''א על הכתוב הזה כהוגן:
@59 **והנה** לשון הכתוב הזה **את שם ה' אלהיך** , כאלו משה ידבר, וכן בכל הדברות אחרי כן, ובשנים הפסוקים הראשונים השם ידבר **אנכי** , **אשר הוצאתיך** , **על פני** , **כי אנכי** , **לאוהבי ולשומרי מצותי** . ומפני זה אמרו רבותינו ז''ל (מכות כד.) אנכי ולא יהיה לך מפי הגבורה שמענום, שהם עיקר הכל. ור''א הקשה כי הכתוב אמר (לעיל פסוק א) וידבר אלהים את כל הדברים האלה, ומפורש מזה את הדברים האלה דבר ה' אל כל קהלכם (דברים ה יט), ושם כתוב עוד ויכתבם על שני לוחות אבנים, כי כאשר אמרם אל כל קהלכם כן כתבם על הלוחות:
@59 **ואני** אפרש לך קבלת רבותינו. בודאי שכל עשרת הדברות שמעו כל ישראל מפי אלהים כפשוטו של כתוב, אבל בשני הדברות הראשונות היו שומעים הדבור ומבינים אותו ממנו כאשר יבין אותם משה, ועל כן ידבר עמהם כאשר ידבר האדון אל עבדו, כמו שהזכרתי. ומכאן ואילך בשאר הדברות ישמעו קול הדבור ולא יבינו אותו, ויצטרך משה לתרגם להם כל דבור ודבור עד שיבינו אותו ממשה. וכך הם מפרשים **משה ידבר והאלהים יעננו בקול** (לעיל יט יט). ועל כן היו בהם דברי ה' עם משה שיאמר להם כן. והכונה היתה בזה כדי שיהיו כלם נביאים באמונת ה' ובאיסור ע''ז, כאשר פירשתי (שם ט), לפי שהם העיקר לכל התורה והמצות, כמו שאמר הקהל לי את העם ואשמיעם את דברי אשר ילמדון ליראה אותי כל הימים (דברים ד י). אבל בשאר הדברות יקבלו מפי משה ביאורן עם שמיעתם קול הדברים, ובשאר המצות יאמינו במשה בכל:
@60 **זכור את יום השבת לקדשו** . אחר שצוה שנאמין בשם המיוחד יתברך שהוא הנמצא, הוא הבורא, הוא המבין, והיכול, ושנייחד האמונה בכל אלה והכבוד לו לבדו, וצוה שנכבד זכר שמו, צוה שנעשה בזה סימן וזכרון תמיד להודיע שהוא ברא הכל, והיא מצות השבת שהיא זכר למעשה בראשית:
@60 ואמר **זכור את יום השבת לקדשו** . ובמשנה תורה (דברים ה יב) כתוב שמור את יום השבת לקדשו. ורבותינו אמרו בזה (ר''ה כז.) זכור ושמור בדבור אחד נאמרו, ולא הקפידו בלשונות אחרים שנתחלפו להם. והכונה להם ז''ל, כי ''זכור'' מצות עשה, צוה שנזכור יום השבת לקדשו ולא נשכחהו, ו''שמור'' אצלם מצות לא תעשה, שכל מקום שנאמר השמר פן ואל אינו אלא לא תעשה (עירובין צו.), יזהיר שנשמור אותו לקדשו שלא נחללהו, ואין ראוי למשה שיחליף דברי השם ממצות עשה למצות לא תעשה. אבל אם החליף בדבור השני וכל תמונה ואמר כל תמונה, בחסרון וא''ו, והוסיף אותה ב''ועל שלשים'', וכן כל כיוצא בזה בשאר הדברות, אין בכך כלום, כי הכל אחד. והטעם הזה לא יסבול אותו אלא מי שאינו רגיל בתלמוד:
@60 **ומפורש** אמרו (ברכות כ:) נשים חייבות בקדוש היום דבר תורה, שנאמר זכור ושמור, כל שישנו בשמירה ישנו בזכירה, והני נשי הואיל ואיתנהו בשמירה איתנהו בזכירה, שהנשים חייבות בשמירה, שבכל מצות לא תעשה הן חייבות, ולא היו חייבות בזכירה שהיא מצות עשה שהזמן גרמא ונשים פטורות, אלא שההיקש הזה מחייב אותן. ואני תמה אם נאמר זכור ושמור מפי הגבורה, למה לא נכתב בלוחות הראשונות. ויתכן שהיה בלוחות הראשונות ובשניות כתוב זכור, ומשה פירש לישראל כי שמור נאמר עמו. וזו כוונתם באמת:
@60 **ובמדרשו** של רבי נחוניא בן הקנה (ספר הבהיר אות קפב) הזכירו עוד סוד גדול בזכור ושמור, ועל הכלל תהיה הזכירה ביום והשמירה בלילה, וזהו מאמר החכמים (ב''ק לב:) שאומרים בערב שבת באי כלה באי כלה, באו ונצא לקראת שבת מלכה כלה, ויקראו לברכת היום קדושא רבא (פסחים קו.) שהוא הקדוש הגדול, ותבין זה. ואמת הוא ג''כ כי מדת זכור רמזו במצות עשה, והוא היוצא ממדת האהבה והוא למדת הרחמים, כי העושה מצות אדוניו אהוב לו ואדוניו מרחם עליו, ומדת שמור במצות לא תעשה, והוא למדת הדין ויוצא ממדת היראה, כי הנשמר מעשות דבר הרע בעיני אדוניו ירא אותו, ולכן מצות עשה גדולה ממצות לא תעשה, כמו שהאהבה גדולה מהיראה, כי המקיים ועושה בגופו ובממונו רצון אדוניו הוא גדול מהנשמר מעשות הרע בעיניו, ולכך אמרו דאתי עשה ודחי לא תעשה, ומפני זה יהיה העונש במצות לא תעשה גדול ועושין בו דין כגון מלקות ומיתה, ואין עושין בו דין במצות עשה כלל אלא במורדין, כמו לולב וציצית איני עושה, סוכה איני עושה, שסנהדרין היו מכין אותו עד שיקבל עליו לעשות או עד שתצא נפשו:
@60 **וכתב** רש''י בפירוש זכור תנו לב לזכור תמיד את יום השבת שאם נזדמן לו חלק יפה יהא מזמינו לשבת, וזו ברייתא היא ששנויה במכילתא (כאן) כך, רבי אלעזר בן חנניה בן חזקיה בן גרון אומר זכור את יום השבת לקדשו, תהא זוכרו מאחד בשבת שאם נזדמן לך חפץ יפה תהא מתקינו לשבת. אבל בלשון יחיד שנויה, ואינה כהלכה, שהרי בגמרא (ביצה טז.) אמרו תניא אמרו עליו על שמאי הזקן כל ימיו היה אוכל לכבוד שבת, כיצד מצא בהמה נאה אומר תהא זו לכבוד שבת, למחר מצא אחרת נאה הימנה מניח השניה ואוכל את הראשונה, אבל הלל הזקן מדה אחרת היתה בו, כל מעשיו היו לשם שמים, שנאמר (תהלים סח כ) ברוך ה' יום יום יעמס לנו. תניא נמי הכי, בית שמאי אומרים בחד בשביך לשבתיך, וב''ה אומרים ברוך ה' יום יום יעמס לנו:
@60 **ובמכילתא** אחרת (מכילתא דרשב''י) שמאי הזקן אומר זכירה עד שלא תבא, שמירה משתבא, ומעשה בשמאי הזקן שלא היה זכרון שבת זז מפיו, לקח חפץ טוב אומר זה לשבת, כלי חדש אומר זה לשבת. אבל הלל הזקן מדה אחרת היתה בו שהיה אומר כל מעשיך יהיו לשם שמים. והלכה היא כדברי ב''ה:
@60 **ועל** דרך הפשט אמרו (במכילתא כאן) שהיא מצוה שנזכור תמיד בכל יום את השבת שלא נשכחהו ולא יתחלף לנו בשאר הימים, כי בזכרנו אותו תמיד יזכור מעשה בראשית בכל עת, ונודה בכל עת שיש לעולם בורא, והוא צוה אותנו באות הזה כמו שאמר (להלן לא יג) כי אות היא ביני וביניכם. וזה עיקר גדול באמונת האל:
@60 וטעם **לקדשו** . שיהא זכרוננו בו להיות קדוש בעינינו, כמו שאמר וקראת לשבת עונג לקדוש ה' מכובד (ישעיה נח יג). והטעם, שתהא השביתה בעינינו בעבור שהוא יום קדוש, להפנות בו מעסקי המחשבות והבלי הזמנים, ולתת בו עונג לנפשינו בדרכי ה', וללכת אל החכמים ואל הנביאים לשמוע דברי ה', כמו שנאמר (מ''ב ד כג) מדוע את הולכת אליו היום לא חדש ולא שבת, שהיה דרכם כן, וכך אמרו רז''ל (ר''ה טז.) מכלל דבחדש ושבת בעי למיזל. וזה טעם שביתת הבהמה, שלא תהא בלבנו מחשבה עליה:
@60 **ולכך** אמרו ז''ל (חולין ה.) שהשבת שקולה כנגד כל מצות שבתורה, כמו שאמרו בע''ז, מפני שבה נעיד על כל עיקרי האמונה בחדוש ובהשגחה ובנבואה. ובמכילתא (כאן) רבי יצחק אומר, לא תהא מונה כדרך שהאחרים מונים, אלא תהא מונה לשם שבת. ופירושה, שהגוים מונין ימי השבוע לשם הימים עצמן, יקראו לכל יום שם בפני עצמו, או על שמות המשרתים, כנוצרים, או שמות אחרים שיקראו להם, וישראל מונים כל הימים לשם שבת, אחד בשבת, שני בשבת, כי זו מן המצוה שנצטוינו בו לזכרו תמיד בכל יום. וזה פשוטו של מקרא, וכך פירש ר''א:
@60 **ואומר** אני שזהו מדרשו של שמאי הזקן (במכילתא דרשב''י) שפירש מצות זכור עד שלא תבא, כלומר שלא נשכחהו בשום פנים, אבל הזכירו בברייתא (בביצה טז:) עוד מדת חסידותו שהיה הוא מזכירו גם במאכליו ואוכל לכבוד שבת כל ימי חייו, והלל עצמו מודה במדרשו של שמאי, אבל היתה בו מדה אחרת במאכלים מפני שכל מעשיו היו לשם שמים, והיה בוטח בה' שיזמין לו לשבת מנה יפה מכל הימים:
@60 **אבל** לרבותינו עוד בו מדרש ממלת לקדשו, שנקדשהו בזכרון, כענין וקדשתם את שנת החמשים שנה (ויקרא כה י), שהוא טעון קדוש ב''ד לומר ביובל מקודש מקודש, אף כאן צוה שנזכור את יום השבת בקדשנו אותו. וכך אמרו במכילתא (כאן) לקדשו, קדשהו בברכה, מכאן אמרו מקדשין על היין בכניסתו, אין לי אלא ליום, ללילה מנין, ת''ל **ושמרתם את השבת** (להלן לא יד), וזהו קדוש היום, והוא מן התורה, אינו אסמכתא. וכך אמרו (ברכות כ:) נשים חייבות בקדוש היום דבר תורה, וזה על קדוש הלילה, לפי שכל הטעונים קדוש מתקדשים בכניסתן פעם אחת, כגון קדוש החדש, וקדוש היובל, אבל ביום אסמכתא, ואין אומרים בו מקודש כלל, שדיינו בפעם אחת בכניסתו. וכן על היין אסמכתא ואינו קבע כלל:
@60 **ובגמרא** פסחים (קו.) אמרו **זכור את יום השבת לקדשו** , זכרהו על היין בכניסתו, אין לי אלא ביום, בלילה מנין, ת''ל **את יום השבת** , האי תנא מהדר אליליא ונסב ליה קרא דיממא, ועוד, עיקר קדושה בלילה הוא, אלא הכי קאמר, **זכור את יום השבת לקדשו** , זכרהו על היין בכניסתו, אין לי אלא בלילה ביום מנין, ת''ל **את יום השבת** . וכן הברייתא שבמכילתא יתרץ בה אין לי אלא בלילה שהוא עיקר הקדוש, ליום מנין וכו', והוא אסמכתא בעלמא. ומשם תלמוד שהמצוה הזאת למדה ממלת ''לקדשו'', אבל **זכור את יום השבת** מצוה לזכרו תמיד בכל יום, כמו שפירשנו, אלא שכל מצות הזכירה במנין אחד בחשבון רמ''ח מצות שנצטווינו. ודע זה:
@61 **ששת ימים תעבוד ועשית כל מלאכתך** . ענין עבודה היא מלאכה שאינה להנאת הגוף כאוכל נפש וכיוצא בה, כענין שנאמר ובכל עבודה בשדה (שמות א יד), כי תעבוד את האדמה (בראשית ד יב), ונעבדתם ונזרעתם (יחזקאל לו ט), וכאשר אפרש עוד בע''ה (ויקרא כג ז). ולכך אמר **ששת ימים תעבוד** את האדמה, **ועשית כל מלאכתך** , אשר היא לצורך גופך ולהנאתך, כענין את אשר תאפו אפו (לעיל טז כג), ובשבת לא תעשה שום מלאכה:
@62 **אתה ובנך ובתך** . הקטנים, הזהירנו בשבת שלא יעשו הבנים הקטנים מלאכה לדעתינו וברצוננו (שבת קכא.):
@62 **ועבדך ואמתך** . העבדים שמלו וטבלו שחייבין בכל דיני השבת כישראל, כמו שאמר במשנה תורה (דברים ה יד) למען ינוח עבדך ואמתך כמוך, ואלו חייבין בכל המצות כנשים, כמו שמפורש בדברי רבותינו (חגיגה ד.) וראוי היה שיזהיר להם בעצמם, כי הם עצמם מצווים בשבת, אבל דבר הכתוב עמנו מפני שהעבדים ברשותינו, לומר ששביתתם עלינו, ואם לא נמנעם אנחנו נענשים עליהם, ועוד, בעבור שעם ישראל ידבר אלהים בכל עשרת הדברות:
@62 **וגרך אשר בשעריך** . על דרך הפשט גר שער לעולם הוא גר תושב שבא לגור בשערי עירנו וקבל עליו שבע מצות בני נח, והוא הנקרא ''גר אוכל נבלות'' (ע''ז סד:) שאמר בו הכתוב (דברים יד כא) לגר אשר בשעריך תתננה ואכלה. ולכן לא היתה בו המצוה שיאמר ''לא תעשה בו מלאכה האזרח והגר'', אבל לנו יצוה שלא יעשה מלאכה לצרכינו כקטנים והבהמה, והוא בעצמו אין עליו זאת המצוה, ועושה מלאכה לעצמו בשבת. והכתוב שאמר (להלן כג יב) **וינפש בן אמתך והגר** , הוא גר צדק שנתיהד וחזר לתורתנו, שצוה אותו בשבת וכן בכל שאר המצות כאשר אמר תורה אחת ומשפט אחד יהיה לכם ולגר הגר אתכם (במדבר טו טז), ולגר ולאזרח הארץ (שם ט יד):
@62 **אבל** מצאנו לרבותינו (במכילתא כאן) שדרשו בהפך, אמרו כי וגרך אשר בשעריך על דרך הפשט הוא גר צדק, והוא חייב כמונו בשביתה, וינפש בן אמתך והגר (להלן כג יב) לרבות גר תושב הערל. ורצונם שיהיה המוזהר תחלה הגר הנימול שחייב כמונו, והכתוב השני לרבות הערל. ולפיכך הוקש לבהמה, שאמר (שם) למען ינוח שורך וחמורך וינפש בן אמתך והגר, צוונו בשביתת כלם בשוה, שלא יעשו לנו, ויעשו כרצונם לעצמם, וכן יהיו העבד והגר הנזכרים בעשרת הדברות שוים, וחייבים בכל דין השבת כמונו, כמו שאמר (דברים ה יד) למען ינוח עבדך ואמתך כמוך:
@63 **ברך ה' את יום השבת ויקדשהו** . אמר שיהיה יום השבת מבורך וקדוש, כי צוה בזכירה לברך אותו ולהדרו, וצוה בשביתה שיהיה לנו קדוש ולא נעשה בו מלאכה. ור''א אמר כי ברך ה' היום הזה וקדשו, שזימן אותו לקבל בו הנפש תוספת חכמה יותר מכל הימים:
@63 **ודרך** האמת כתבתיו (בבראשית ב ב) בפסוק ויכלו, ומשם תשכיל ותבין:
@63 **כי ששת ימים עשה ה'** . לא יחסר בי''ת, אבל כי ששת ימים עשה ה' וביום השביעי שבת וינפש (להלן לא יז):
@64 **כבד את אביך** . הנה השלים כל מה שאנו חייבין בדברי הבורא בעצמו ובכבודו, וחזר לצוות אותנו בעניני הנבראים, והתחיל מן האב שהוא לתולדותיו כענין בורא משתתף ביצירה, כי השם אבינו הראשון, והמוליד אבינו האחרון, ולכך אמר במשנה תורה (דברים ה טז) כאשר צויתיך בכבודי כן אנכי מצוך בכבוד המשתתף עמי ביצירתך. ולא פירש הכתוב הכבוד, שהוא נלמד מן הכבוד הנאמר למעלה באב הראשון יתברך, שיודה בו שהוא אביו ולא יכפור בו לאמר על אדם אחר שהוא אביו, ולא יעבדנו כבן לירושתו, או לענין אחר שיצפה ממנו, ולא ישא שם אביו וישבע בחיי אביו לשוא ולשקר. ויכנסו בכלל הכבוד דברים אחרים, כי בכל כבודו נצטווינו, ומפורשים הם בדברי רבותינו (קדושין לא:), וכבר אמרו (שם ל:) שהוקש כבודו לכבוד המקום:
@64 **וכאשר** המצוה הזאת היא בתחתונים, כן נתן שכרה באריכות ימים בארץ אשר יתן לנו. ועל דעת רבותינו (קידושין לט:) ענין הכתוב **למען יאריכון ימיך ועל האדמה** , יבטיח כי במצוה הזאת יהיו כל ימותינו ארוכים, כי ימלא השם ימינו בעולם הזה, ויהיו ארוכים בעולם הבא שכלו ארוך, ותהיה ישיבתינו לעד על האדמה הטובה שיתן לנו, ובמשנה תורה (דברים ה טז) פירש למען יאריכון ימיך ולמען ייטב לך על האדמה, והנה הם שתי הבטחות:
@65 **לא תרצח לא תנאף לא תגנב** . אמר, הנה צויתיך להודות שאני בורא את הכל בלב ובמעשה, ולכבד האבות בעבור שהם משתתפים ביצירה, אם כן השמר פן תחבל מעשה ידי ותשפוך דם האדם אשר בראתי לכבודי ולהודות לי בכל אלה, **ולא תנאף** אשת רעך, כי תחבל ענין כבוד האבות לכפור באמת ולהודות בשקר, כי לא ידעו את אביהם ויתנו כבודם לאחר, כאשר יעשו עובדי ע''ז אומרים לעץ אבי אתה (ירמיה ב כז), ולא ידעו אביהם שבראם מאין. ואחר כן הזהיר **לא תגנוב** נפש, כי הוא כמו כן גורם כזאת. וכן סדר המצות בחומרן ועונשן כך הוא, אחר ע''ז שפיכות דמים, ואחרי כן גלוי עריות ואחר כך הזהיר גנבת נפש ועדות שקר וגזל. ומי שלא יחמוד לא יזיק לעולם לחברו. והנה השלים כל מה שאדם חייב בשל חברו. ואחר כן יבאר המשפטים בפרט, כי המתחייב לחבירו במשפט מן המשפטים אם לא יחמוד ולא יתאוה למה שאינו שלו ישלם מה שעליו:
@65 **ואמר** ר''א (בהקדמה לעשרת הדברות) כי אחז הכתוב דרך ארץ לאמר תחלה בית רעך, כי המשכיל יקדים להיות לו בית ואחרי כן יקח אשה להביאה אל ביתו, ואחרי כן יקנה עבד ואמה. ובמשנה תורה הזכיר האשה תחלה, כי הבחורים יתאוו לשאת אשה תחלה. או שחמדת האשה האיסור הגדול שבהם. והנה עשרת הדברות חמשה בכבוד הבורא וחמשה לטובת האדם, כי **כבד את אביך** כבוד האל, כי לכבוד הבורא צוה לכבד האב המשתתף ביצירה, ונשארו חמשה לאדם בצרכו וטובתו:
@65 **והנה** הזכיר בקצת הדברות גמולם, ובקצתם לא הזכיר, כי בדבור השני **אל קנא** , בשלישי **כי לא ינקה** , בחמישי **למען יאריכון** , ולא הזכיר באחרים עונש או שכר. והיה זה, כי החמשה דברים האחרונים טובת האדם הם, והנה שכרו אתו ופעולתו לפניו. אבל בע''ז צריך אזהרת עונש לחומר הגדול שבה, והוא לכבוד הבורא:
@65 **והנראה** אלי כי אמר **אל קנא** , על **לא יהיה לך** , ואמר **ועושה חסד** , על **אנכי** , כי העונש יבא על מצות לא תעשה, והשכר על מצות עשה. וקבלת מלכות האל ואזהרת עבודת זולתו ענין אחד, והשלים הדבר ואחר כך הזהיר על העובר, והבטיח בשכר על העושה. והזהיר בשבועת שוא בעונש **לא ינקה** , ולא הזכיר בשבת גמול כלל, ולא אמר על המחלל השבת עונש הכרת או עונש אחר זולתו, ולא הזכיר שכר על השומר שבת מחללו, מפני שהשבת נכלל בשתי מצות הראשונות, כי השומר שבת מעיד על מעשה בראשית ומודה במצות **אנכי** , והמחללו מכחיש במעשה בראשית ומודה בקדמות העולם להכחיש במצות **אנכי** , והנה הוא בכלל **אל קנא פוקד** , ובכלל **ועושה חסד לאלפים** . ובדבור החמשי בכבוד האבות הזכיר שכר כי היא מצות עשה:
@65 **והנראה** במכתב הלוחות שהיו החמש ראשונות בלוח אחד שהם כבוד הבורא כמו שהזכרתי, והחמש השניות בלוח אחד, שיהיו חמש כנגד חמש, כענין שהזכירו בספר יצירה (א ג) בעשר ספירות בלי מה כמספר עשר אצבעות, חמש כנגד חמש, וברית יחיד מכוונת באמצע. ומזה יתברר לך למה היו שתים, כי עד **כבד את אביך** הוא כנגד תורה שבכתב, ומכאן ואילך כנגד תורה שבעל פה. ונראה שלזה רמזו רבותינו ז''ל שאמרו (תנחומא עקב י) שתי לוחות כנגד שמים וארץ וכנגד חתן וכלה וכנגד שני שושבינין וכנגד שני עולמים. וכל זה רמז אחד, והמשכיל יבין הסוד:
@67 (טו~טז) **וכל העם רואים את הקולות ויאמרו אל משה** . דעת המפרשים שהיה זה אחר מתן תורה, והוא שאמר (דברים ה כ~כב) ותקרבון אלי כל ראשי שבטיכם וזקניכם ותאמרו הן הראנו ה' אלהינו וגו' אם יוספים אנחנו לשמוע את קול ה' עוד ומתנו וגו'. ואין כן דעתי, בעבור שאמר בכאן ואל ידבר עמנו אלהים, ולא אמר ''עוד'', ומשה אמר בכאן אל תיראו, ושם נאמר (שם ה כה) הטיבו כל אשר דברו. ועוד, כי בכאן לא ספר שיפחדו רק מן הקולות והלפידים ומן ההר שהוא עשן, ושם פחדו מדבור השכינה, שאמרו כי מי כל בשר אשר שמע קול אלהים חיים מדבר מתוך האש כמונו ויחי (שם ה כג). ועוד, כי בכאן (בפסוק כא) אמר ומשה נגש אל הערפל, ולא אמר שבא בתוכו:
@67 **והנכון** בעיני בפרשה ובסדור הענין, כי וכל העם רואים ויאמרו אל משה היה קודם מתן תורה, ומתחלה הזכיר כסדר כל דברי האלהים מה שצוה למשה בהגבלת ההר ואזהרת העם ועשרת הדברות, ועתה חזר והזכיר דברי העם אל משה ואמר כי מעת שראו את הקולות ואת הלפידים נעו לאחור ועמדו מרחוק יותר מגבול ההר אשר הגביל משה:
@67 **והסדר** בדברים, כי בבקר היו קולות וברקים וקול שופר חזק (לעיל יט טז) ועדין לא ירדה שכינה, כענין ורוח גדולה וחזק מפרק הרים משבר סלעים לפני ה' לא ברוח ה' (מ''א יט יא), וחרדו העם במחנה במקום תחנותם (לעיל יט טז), ומשה חזק לבם והוציאם לקראת האלהים ויתיצבו בתחתית ההר (שם יז), ובהיותם שם בתחתית ההר מצפים ומתיצבים ירד ה' על ההר באש (שם יח), ויעל עשנו עד לב השמים חשך ענן וערפל (דברים ד יא), וחרד ההר עצמו ונזדעזע (לעיל יט יח) כאשר יעשו ברעש הנקרא ''זלזלה'' או יותר מכן. וכן כתוב (תהלים קיד ד) ההרים רקדו כאלים גבעות כבני צאן, ואיננו משל, כאשר איננו משל הים ראה וינס הירדן יסב לאחור (שם ג), ונתחזק קול השופר מאד (לעיל יט יט), אז ראו העם וינועו לאחור ויעמדו מרחוק (כאן) יותר מן הגבול, ואז אמרו אליו כלם שלא ידבר עמהם האלהים כלל פן ימותו, כי במראה נהפכו ציריהם עליהם ולא עצרו כח (דניאל י טז), ואם ישמעו הדבור ימותו, ומשה חזקם ואמר להם אל תיראו (פסוק כ), ושמעו אליו ויעמוד העם מרחוק במעמדם (פסוק כא), כי לא רצו בכל דבריו להתקרב אל הגבול, ומשה נגש אל הערפל (שם), לא בא בתוכו, ואז דבר אלהים עשרת הדברות:
@67 **ואחר** עשרת הדברות לא הזכיר כאן מה שאמרו הזקנים למשה, כי רצה לבאר כסדר המצות והמשפטים, אבל במשנה תורה (דברים ה כ) הזכיר משה כי אחרי הדברות קרבו אליו כל ראשי שבטיהם וזקניהם ואמרו לו אם יוספים אנחנו לשמוע את קול ה' אלהינו עוד ומתנו, כי שערנו בנפשותינו שלא נוכל עוד לסבול משא דבר ה' אלהים, כי חשבו שירצה האלהים לדבר אליהם כל המצוות, ולכך אמרו קרב אתה ושמע את כל אשר יאמר ה' אלהינו ואת תדבר אלינו ושמענו ועשינו (שם כד), והקב''ה הודה לדבריהם ואמר הטיבו כל אשר דברו, כי כן היה החפץ לפניו שלא ישמיעם רק עשרת הדברות, והיראה ישרה לפניו:
@67 **וינועו** . על דעת רבותינו (במכילתא כאן) אין נוע בכאן אלא זיע, וכן הוא אומר (ישעיה כד כ) נוע תנוע ארץ כשכור, ואם כן יאמר כי נזדעזעו, ומפחדם חזרו עוד לאחור ועמדו מרחוק. ועל דעת בעלי הפשט וינועו שנעו ממקומם לאחוריהם ועמדו מרחוק, מלשון נע ונד תהיה בארץ (בראשית ד ב), וכן ויניעם במדבר (במדבר לב יג):
@68 **ואל ידבר עמנו אלהים** . השגיח הרב במורה הנבוכים (ב לג) באונקלוס שתרגם **ואל ידבר עמנו אלהים** , ואל יתמלל עמנא מן קדם ה', ולא עשה כן בשאר המקומות, כי תרגם וידבר אלהים את כל הדברים האלה (לעיל כ א) ומליל ה', וכן בכל מקום וידבר ה' אל משה, ומליל ה', והטעם אצלו, כי הדיבור הראשון אע''פ ששמעוהו כל ישראל אין מעלתם בו כמעלת משה רבינו. וא''כ כדעתו למה תרגם כי מן השמים דברתי עמכם (פסוק כב) מללית עמכון, והיה לו לומר איתמלל מן קדמי עמכון, וכן במשנה תורה (דברים ה יט) את הדברים האלה דבר ה' אל כל קהלכם, תרגם אותו מליל ה', וכן אמרו הם ואת קולו שמענו (שם כא), ותרגם ית קל מימריה שמענא יומא דין חזינא ארי ימלל ה' עם אינשא, וכן פנים בפנים דבר ה' עמכם (שם ד) מליל ה', ועוד, שהרי תרגם והאלהים יעננו בקול (לעיל יט יט) ומן קדם ה' מתעני ליה בקל, וכבר בא בלשון התורה כן במשה עצמו, וישמע את הקול מדבר אליו (במדבר ז פט), ותרגומו מתמלל, וכן ירד עמוד הענן ועמד פתח האהל ודבר עם משה (להלן לג ט) ומתמלל:
@68 **אבל** הטעם לאונקלוס מבואר, שלא נאמר בכל מתן תורה דבור השם לישראל רק מתוך האש (דברים ה כא), ומן האש שמעו, והוא מה שהשיגו הם, וכן כי מן השמים (פסוק יט) על דרך האמת, מתוך השמים, והוא מתוך האש בשוה, וכבר נתבאר ענינו (לעיל יט כ). והנה כשראה אונקלוס בכאן **ואל ידבר עמנו אלהים** שלא הוזכר בו מחיצה, לא ראה לתרגם בו ולא ימלל עמנא ה', ואין בלשונו כנוי למלת אלהים, ולכך שלל בכאן מהם הדבור ממש:
@68 **ומן** המופלא בחכמת אונקלוס שלא הזכיר במעמד הר סיני ''יקרא דה''' או ''מימרא דה''', ותרגם הא אנא מתגלי לך (שם ט), יתגלי ה' לעיני כל עמא על טורא דסיני (שם יא), דאתגלי עלוהי (שם יח), ואתגלי ה' על טורא דסיני (שם כ), ולא תרגם ''ואיתגלי יקרא דה''' כאשר הוא מתרגם תחלה הר האלהים (לעיל ג א) טורא דאיתגלי עלוהי יקרא דה', כן עשה בכל מקום שהזכיר השם המיוחד בירידה הזאת, אבל כאשר יזכיר הכתוב אלהים תרגם לקראת האלהים (לעיל יט יז) לקדמות מימרא דה', ותרגם בא האלהים (כ יז) יתגלי לכון יקרא דה', ולא אמר יתגלי לכון ה', דתמן יקרא דה' (שם יח), וכן אמר ומן קדם ה' מתעני ליה בקל (לעיל יט יט), וכל זה מבואר ומפורש למי שישכיל דברינו המפורשים למעלה (יט כ). וכן ראיתי בנוסחאות מדוקדקות ויעל משה אל הר האלהים (להלן כד יג) וסלק משה לטורא דה', כי אחרי מתן תורה יאמר כן, וכתיב ויסעו מהר ה' (במדבר י לג):
@69 **כי לבעבור נסות אתכם בא האלהים** . לגדל אתכם בעולם שיצא לכם שם בגוים שהוא בכבודו נגלה עליכם. נסות, לשון הרמה וגדולה, כמו הרימו נס (ישעיה סב י), כנס על הגבעה (שם ל יז), שהוא זקוף, לשון רש''י. ואיננו נכון. אבל יתכן שיאמר, כי **לבעבור** הרגילכם באמונתו **בא האלהים** , שכיון שהראה לכם גלוי השכינה נכנסה אמונתו בלבבכם לדבקה בו, ולא תפרד נפשכם ממנה לעולם, **ולמען תהיה יראתו על פניכם** בראותכם כי הוא לבדו האלהים בשמים ובארץ ותיראון ממנו יראה גדולה. או יאמר, שתהיה על פניכם יראת האש הגדולה הזאת ולא תחטאו מיראתכם ממנה. ויהיה הלשון מן ויואל ללכת כי לא נסה, ויאמר דוד אל שאול לא אוכל ללכת באלה כי לא נסיתי (ש''א יז לט), כענין רגילות:
@69 **והרב** אמר במורה הנבוכים (ג כד) כי אמר להם **אל תיראו** , כי זה אשר ראיתם היה שכשינסה ה' אלהים אתכם להודיע ערך אמונתכם, וישלח לכם נביא שקר שירצה לסתור מה ששמעתם, לא תמעד אשוריכם לעולם מדרך האמת, כי כבר ראיתם האמת בעיניכם. ואם כן יאמר, בעבור שיוכל לנסות אתכם לעתיד **בא האלהים** עתה כדי שתהיו עומדים לו בכל נסיון:
@69 **ועל** דעתי הוא נסיון ממש. יאמר, הנה רצה האלהים לנסותכם התשמרו מצותיו כי הוציא מלבכם כל ספק, ומעתה יראה הישכם אוהבים אותו ואם תחפצו בו ובמצותיו. וכן כל לשון נסיון בחינה, ללכת באלה כי לא נסיתי (ש''א יז לט), לא בחנתי נפשי מעולם ללכת בהם. ויתכן שיהיה הנסיון הזה בטובה, כי האדון פעם ינסה עבדו בעבודה קשה לדעת אם יסבלנה לאהבתו, ופעם ייטיב עמו לדעת אם יגמול אותו בטובה אשר עשה עמו להוסיף לאדוניו עבודה וכבוד, כענין שאמרו חכמים (שמו''ר לא כ) אשרי אדם שעומד בנסיוניו, שאין לך בריה שאין הקב''ה מנסה אותה, העשיר מנסה אותו אם תהיה ידו פתוחה לעניים, העני מנסה אותו אם יוכל לקבל יסורין וכו'. ולכך אמר הכתוב, הטיב לכם האלהים להראותכם את כבודו, אשר לא עשה כן לכל גוי, לנסותכם אם תגמלו לפניו כטובה אשר עשה עמכם להיות לו לעם נחלה, כענין שאמר הלה' תגמלו זאת (דברים לב ו), ואמר רק אתכם ידעתי מכל משפחות האדמה על כן אפקוד עליכם את כל עונותיכם (עמוס ג ב), כי העמים אינם חייבים לי ככם אשר ידעתי אתכם פנים בפנים:
@71 **אתם ראיתם כי מן השמים דברתי עמכם** . צוה שיאמר להם אחרי שראיתם בעיניכם כי **מן השמים דברתי עמכם** ואני הוא האדון בשמים ובארץ, אל תשתפו עמי אלהי כסף ואלהי זהב כי אין לכם צורך אתי אל עזר אחר, ושיעור הכתוב **לא תעשון אתי אלהי כסף ולא תעשו לכם אלהי זהב** . ולדעתי פירושו לא תעשון אלהי כסף ואלהי זהב להיות לכם לאלהים אתי, ולא תעשו לכם כלל, הזהיר מן האמונה בהם, וחזר והזהיר מן העשייה לבדה, כענין ופסל ומצבה לא תקימו לכם (ויקרא כו א):
@71 **ועל** דרך האמת טעם ''אתי'' כטעם על פני, וכבר רמזתי פירושו (לעיל פסוק ג):
@71 **וכתב** רש''י כי מן השמים דברתי עמכם, וכתוב אחר אומר וירד השם על הר סיני (לעיל יט כ), בא השלישי להכריע ביניהם מן השמים השמיעך את קולו ליסרך ועל הארץ הראך את אשו הגדולה (דברים ד לו), כבודו בשמים ואשו וגבורתו בארץ. זהו לשון הרב. ואיננו מכוון. אבל הכרע הפסוקים מדרש חכמים הוא (מכילתא כאן), ואמת הוא כי השם בשמים וכבודו בהר סיני כי באש ה', וכתוב ועל הר סיני ירדת ודברת עמהם משמים, והמקראות כלן מבוארות בלשונן לכל יודע, וכבר בארתי הכל למעלה (לעיל יט כ). ורבי אברהם אמר כי מי שיש לו לב יבין הטעם בפרשת כי תשא (שמות לג כא). ודברי פי חכם חן (קהלת י יב).
@73 **מזבח אדמה תעשה לי** . פירש ר''א כי אמר **לא תעשון אתי אלהי כסף ואלהי זהב** לקבל כח עליונים בצורתם להיות אמצעיים ביני וביניכם, כי **בכל המקום אשר אזכיר את שמי אבא אליך** אני בכבודי **וברכתיך** , אין לך צורך לאמצעי כלל. ועל דעת רבותינו (במכילתא כאן) במזבחות, שהם הנעשים במשכן ובמקדש, הזכיר מצות המזבחות באדמה ובאבנים לאמר שיעשו גם כן המזבחות לשם לבדו, ושם יזבחו העולות והשלמים, ולא לשדים על פני השדה, ובכל המקום אשר יזכירו את שמו יבא בכבודו עליהן לשכן שכינתו בתוכם ולברך אותם:
@74 (כב~כג) וטעם **ואם** . במצות חובה, לומר, אם יגיע הזמן שתזכו לרשת הארץ ולבנות לי מזבח אבנים בבית הבחירה, השמר שלא תבנה אתהן גזית שתחשוב לעשות כן למעלת הבנין. ודעת ר''א שהמצוה על מזבח הברית שבסדר ואלה המשפטים (להלן כד ד) בפירושיו:
@74 **ועל** דרך האמת, הכתובים כסדרן, **אתם ראיתם כי מן השמים דברתי עמכם** בשמי הגדול, **ולא תעשון על פני אלהי כסף ואלהי זהב** , אבל אני מתיר לכם שתעשו מזבח לי לבדי ולזבוח עליו עולות גם שלמים **בכל המקום אשר אזכיר את שמי כי אבא אליך וברכתיך** , ברכות שמים מעל ברכות תהום רובצת תחת (בראשית מט כה), ו''אזכיר'' מן זכרנו יברך (תהלים קטו יב):
@74 **כי חרבך הנפת עליה** . לאסור בהם נגיעת הברזל, כמו שנאמר אבנים שלמות תבנה את מזבח ה' אלהיך (דברים כז ו), לא תניף עליהן ברזל (שם ה). והזכיר כאן הברזל בלשון חרב, כי כל כלי ברזל אשר בהם פיות כורתות יקראו חרב. יאמר בסיף, ויעש לו אהוד חרב ולה שני פיות (שופטים ג טז), ובאזמל, קח לך חרב חדה (יחזקאל ה א), ויאמר בכשיל וכלפות אשר יסתרו בו הבנין ומגדלותיך יתץ בחרבותיו (שם כו ט), וכן זה המסתת אבנים יקראנו חרב:
@74 **וטעם** המצוה בדברי רבותינו (במכילתא כאן) להדור מצוה שלא יונף המקצר על המאריך. ור''א אמר שלא ישאר הנפסל מן האבן באשפתות והמקצת בנוי במזבח השם. או שלא ילקח ממנה לעשות מזבח לע''ז כי עובדיה יעשו כן אולי יצליחו. והרב אמר במורה הנבוכים (ג מה) שהיא הרחקה, שלא יבאו לעשות בהן צורה ותהיה אבן משכית, כי היה כן מנהג עובדי ע''ז:
@74 **ואני** אומר כי טעם המצוה, בעבור היות הברזל חרב והוא המחריב העולם, ולכן נקרא כך. והנה עשו אשר שנאו השם (מלאכי א ג) הוא היורש החרב, שאמר לו ועל חרבך תחיה (בראשית כז מ), והחרב הוא כחו בשמים ובארץ, כי במאדים ובמזלות הדם החרב יצליח, ובהם תראה גבורתו, ולכן לא יובא בית ה':
@74 **וזהו** הטעם שהזכירו הכתוב בפירוש **אשר לא תבנה אתהן גזית** , כי בהניפך עליהם שום ברזל לעשותם כן **הנפת עליה חרבך** המרצח ומרבה חללים וחללת אותה:
@74 **ומפני** זה לא היה במשכן ברזל, כי גם יתידותיו שהיו טובות יותר מברזל, עשה נחשת. וכן בבית עולמים לא נעשה בו כלי ברזל מלבד הסכינים, כי השחיטה אינה עבודה. והכתוב לא אסר לבנות גזית רק בהניף עליהן ברזל, כי פירש כאשר חרבך הנפת עליה, ומפורש בזה לא תניף עליהן ברזל (דברים כז ה), ואם בא לסתת אותן בכלי כסף או בשמיר שהזכירו רבותינו (סוטה מח:) הרי זה מותר, אע''פ שאינן שלמות. וזה ישבר טעמו של ר''א. גם טעם הרב בעבור זה איננו נכון:
@74 **והנה** שלמה הוסיף במצוה שלא נשמע כל כלי ברזל בבית בהבנותו (מ''א ו ז), אע''פ שהיה מותר, שכך שנינו במכילתא (כאן) לא תבנה אתהן גזית, בו אי אתה בונה אבל אתה בונה בהיכל ובקדשי קדשים, ומה אני מקיים ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהבנותו, בבית אינו נשמע אבל בחוץ נשמע. והיה הענין הזה, שהיו עוקרין האבנים מהרריהן בכלי ברזל ומסתתים אותם שם בברזל, כאשר יכרתו ג''כ בברזל העצים והברושים אשר היו בבית, וכן כתוב (שם ה לא) ויסיעו אבנים גדולות אבנים יקרות ליסד הבית אבני גזית. וכאשר יביאו אותן אל הבית לבנות הקירות לא יתקנו אותם בברזל ולא יניפו אותו עליהן כלל כדרך הבונים:
@74 **וזהו** שאמר (שם ו ז) אבן שלמה מסע נבנה, לא שהיא שלימה לגמרי, רק שהיא שלימה שאין בה פגם כדי שתחגור בה צפורן, אבל היא חלקה ושוה (ס''א ונאה). ופירוש ''מסע'', שהיא גדולה כאשר הסיעו אותה מן ההר, לא חלקו הסלע לאבנים מרובות כמנהג הבונים, ולא יתקנו אותה בכאן, ולא ישיבוה במקבות והגרזן כמנהג כל בנין אחר, כי לא רצה שלמה שיבנה ושישמע בכל הר הבית קול ברזל, וכל זה להרחיק הברזל ממנו, וזה כדעת רבי ירמיה במסכת סוטה (מח:). אבל לדעת רבי יהודה (שם) אבני גזית בביתו שם אותן, לא בבית המקדש. ועל דעתו פירוש המקרא ויסיעו אבנים גדולות אבנים יקרות ליסד את הבית אבני גזית (מ''א ה לא), כלומר שהסיעו גם אבני גזית והם לביתו. וכן נראה בפשט הכתוב כי החצר עשה אבני גזית, דכתיב (שם ו לו) ויבן את החצר שלשה טורי גזית, ולא החמיר רק בהיכל ובדביר. וכל זה ריחוק הברזל מן הקדש. והברזל אשר הקדיש דוד שלא נחקר משקלו (דהי''א כב יד), לעשות ממנו כלים לכרות העצים ולחצוב האבנים היה:
@75 **ולא תעלה במעלות על מזבחי** . בעבור כי התחיל לצוות במזבח השלים מצותו ולא איחר זה עד צוותו בדברי הקרבנות בתורת כהנים, וזו ראיה לדברי חכמים ואין צריכין חיזוק. וטעם המעלות, יראת המזבח והדורו לכבוד השם. ולמצות השם טעמים רבים בכל אחת, כי יש בכל אחת תועלות רבות לגוף ולנפש:
